contracts/TrainingPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ITPMinDelay {
    function getMinDelay() external view returns (uint256);
}

/// @title TrainingPool: the staked workers of the training market (testnet)
/// @notice Workers that train, spot-check and evaluate Neuro's model (TrainingMarket,
///         docs/future/useful-work-training.md) stake here first. The stake is what a fake checkpoint or a
///         wrong / missing answer costs: a market that governance names (`markets`) may lock a member while
///         it holds a seat or an assignment (`busy`) and slash it (the slashed coins go to that market).
///         A member who leaves stops being drawn at once and gets its stake back after `exitDelay`, once
///         nothing is locked (longer than a whole task, so a cheater cannot leave before it is judged).
///         No admin key: governance must be a timelock with at least MIN_DELAY.
contract TrainingPool {
    uint256 public constant MIN_DELAY = 2 days;

    struct Member {
        uint128 stake;
        uint64 exitAt;
        uint32 busy;
        uint32 index; // position in `members` + 1 (0: not in the pool)
    }

    address public governance;
    uint128 public minStake;
    uint32 public exitDelay;
    uint256 public totalStake;
    mapping(address => bool) public markets;
    mapping(address => Member) public memberOf;
    address[] public members;

    event Joined(address indexed member, uint256 stake);
    event Exiting(address indexed member, uint64 at);
    event Withdrawn(address indexed member, uint256 amount);
    event Slashed(address indexed member, address indexed market, uint256 amount);
    event MarketSet(address indexed market, bool on);
    event ParamsSet(uint128 minStake, uint32 exitDelay);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotMarket();
    error NotTimelock();
    error BadValue();
    error WrongPhase();
    error Busy();

    constructor(address governance_, uint128 minStake_, uint32 exitDelay_) {
        _checkTimelock(governance_);
        governance = governance_;
        _setParams(minStake_, exitDelay_);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    modifier onlyMarket() {
        if (!markets[msg.sender]) revert NotMarket();
        _;
    }

    // ---------------------------------------------------------------- members

    /// Stakes (or adds stake); a member who was leaving is back in the draw.
    function join() external payable {
        Member storage m = memberOf[msg.sender];
        m.stake += uint128(msg.value);
        totalStake += msg.value;
        if (m.stake < minStake) revert BadValue();
        m.exitAt = 0;
        if (m.index == 0) {
            members.push(msg.sender);
            m.index = uint32(members.length);
        }
        emit Joined(msg.sender, m.stake);
    }

    /// Leaves the draw now; the stake comes back after exitDelay (it can still be slashed until then).
    function exit() external {
        Member storage m = memberOf[msg.sender];
        if (m.index == 0 || m.exitAt != 0) revert WrongPhase();
        m.exitAt = uint64(block.timestamp + exitDelay);
        emit Exiting(msg.sender, m.exitAt);
    }

    function withdrawStake() external {
        Member storage m = memberOf[msg.sender];
        if (m.exitAt == 0 || block.timestamp < m.exitAt) revert WrongPhase();
        if (m.busy != 0) revert Busy();
        uint256 amount = m.stake;
        m.stake = 0;
        m.exitAt = 0;
        totalStake -= amount;
        uint256 i = m.index - 1;
        address last = members[members.length - 1];
        members[i] = last;
        memberOf[last].index = uint32(i + 1);
        members.pop();
        m.index = 0;
        (bool ok, ) = msg.sender.call{value: amount}("");
        if (!ok) revert BadValue();
        emit Withdrawn(msg.sender, amount);
    }

    /// In the draw: staked at least minStake and not leaving.
    function eligible(address w) external view returns (bool) {
        Member storage m = memberOf[w];
        return m.index != 0 && m.exitAt == 0 && m.stake >= minStake;
    }

    function size() external view returns (uint256) {
        return members.length;
    }

    // ---------------------------------------------------------------- markets

    /// Locks (+1) or releases (-1) a member while a market holds a seat or an assignment of it.
    function lock(address w, bool on) external onlyMarket {
        if (on) memberOf[w].busy++;
        else memberOf[w].busy--;
    }

    /// Takes up to `amount` of a member's stake (what is there) and sends it to the calling market.
    function slash(address w, uint256 amount) external onlyMarket returns (uint256 got) {
        Member storage m = memberOf[w];
        got = amount < m.stake ? amount : m.stake;
        if (got == 0) return 0;
        m.stake -= uint128(got);
        totalStake -= got;
        emit Slashed(w, msg.sender, got);
        (bool ok, ) = msg.sender.call{value: got}("");
        if (!ok) revert NotMarket();
    }

    // ---------------------------------------------------------------- governance (a timelock)

    function setMarket(address market, bool on) external onlyGovernance {
        markets[market] = on;
        emit MarketSet(market, on);
    }

    function setParams(uint128 minStake_, uint32 exitDelay_) external onlyGovernance {
        _setParams(minStake_, exitDelay_);
    }

    function setGovernance(address next) external onlyGovernance {
        _checkTimelock(next);
        governance = next;
        emit GovernanceSet(next);
    }

    function _setParams(uint128 minStake_, uint32 exitDelay_) internal {
        if (minStake_ == 0 || exitDelay_ == 0) revert BadValue();
        minStake = minStake_;
        exitDelay = exitDelay_;
        emit ParamsSet(minStake_, exitDelay_);
    }

    function _checkTimelock(address t) internal view {
        if (t.code.length == 0) revert NotTimelock();
        try ITPMinDelay(t).getMinDelay() returns (uint256 d) {
            if (d < MIN_DELAY) revert NotTimelock();
        } catch {
            revert NotTimelock();
        }
    }
}

contracts/TwapRecorder.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The Uniswap-V2 pair surface (ZetaphyPair) the recorder reads.
interface ITwapPair {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function price0CumulativeLast() external view returns (uint256);
    function price1CumulativeLast() external view returns (uint256);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

/// @title TwapRecorder: observations of DEX pairs' cumulative prices, for TWAPs
/// @notice A Uniswap-V2 pair (ZetaphyPair) keeps price0/price1CumulativeLast:
///         the running sum of its price times the seconds it held, updated at
///         the FIRST trade of a block with the reserves from before it. A TWAP
///         over [t0, t1] is (cumulative(t1) - cumulative(t0)) / (t1 - t0); it
///         needs cumulative(t0) remembered, which is what this contract does.
///         No owner, no settings after deployment. Anyone (a keeper, the relay,
///         a user) may call record(pair):
///           - at most one observation per pair every `minSpacing` seconds and
///             never two in one block, so pokes cannot flood the ring;
///           - an observation is the cumulative price as of now, counted with
///             the reserves from before this block's first trade (the pair's
///             own rule), so a swap in the same transaction or block as the
///             record (or as the read) adds nothing to the average;
///           - it also keeps sqrt(reserve0 * reserve1) (pool depth that swaps
///             cannot lower), so a reader can require depth at every observation
///             of its window, not only at the moment it reads.
///         consult() returns the window's average and what a reader needs to
///         judge it (oldest time, observation count, smallest depth, the
///         largest gap of one segment's average from the window's average).
contract TwapRecorder {
    struct Observation {
        uint64 time;
        uint128 depth;   // sqrt(reserve0 * reserve1), raw units
        uint256 cum0;    // price0Cumulative (UQ112x112 seconds), wraps by design
        uint256 cum1;
    }

    uint16 public constant CAPACITY = 96;
    uint32 public immutable minSpacing;

    mapping(address => Observation[CAPACITY]) private _obs;
    mapping(address => uint16) public nextIndex;
    mapping(address => uint16) public count;

    event Observed(address indexed pair, uint64 time, uint256 cum0, uint256 cum1, uint128 depth);

    error NotEnoughHistory();
    error EmptyPool();

    constructor(uint32 minSpacing_) {
        require(minSpacing_ >= 1, "spacing");
        minSpacing = minSpacing_;
    }

    /// Records an observation if minSpacing has passed since the last one. Returns whether it did.
    function record(address pair) external returns (bool) {
        uint16 n = count[pair];
        if (n != 0) {
            Observation storage last = _obs[pair][(nextIndex[pair] + CAPACITY - 1) % CAPACITY];
            if (block.timestamp < uint256(last.time) + minSpacing) return false;
        }
        (uint256 c0, uint256 c1, uint128 d) = current(pair);
        if (d == 0) revert EmptyPool();
        uint16 i = nextIndex[pair];
        _obs[pair][i] = Observation(uint64(block.timestamp), d, c0, c1);
        nextIndex[pair] = (i + 1) % CAPACITY;
        if (n < CAPACITY) count[pair] = n + 1;
        emit Observed(pair, uint64(block.timestamp), c0, c1, d);
        return true;
    }

    /// The pair's cumulative prices as of now (Uniswap's currentCumulativePrices) and its depth.
    function current(address pair) public view returns (uint256 c0, uint256 c1, uint128 depth) {
        c0 = ITwapPair(pair).price0CumulativeLast();
        c1 = ITwapPair(pair).price1CumulativeLast();
        (uint112 r0, uint112 r1, uint32 last) = ITwapPair(pair).getReserves();
        uint32 nowTs = uint32(block.timestamp);
        if (last != nowTs && r0 != 0 && r1 != 0) {
            unchecked {
                uint32 elapsed = nowTs - last; // wraps, as in the pair
                c0 += ((uint256(r1) << 112) / r0) * elapsed;
                c1 += ((uint256(r0) << 112) / r1) * elapsed;
            }
        }
        depth = uint128(_sqrt(uint256(r0) * uint256(r1)));
    }

    /// The i-th newest observation (0 = newest).
    function observation(address pair, uint16 i) public view returns (Observation memory) {
        require(i < count[pair], "index");
        return _obs[pair][(nextIndex[pair] + CAPACITY - 1 - i) % CAPACITY];
    }

    struct Twap {
        uint256 avg0;          // UQ112x112: token1 per token0 (raw units), over [from, now]
        uint256 avg1;          // token0 per token1
        uint64 from;           // the observation the window starts at (at least `window` old)
        uint64 newest;         // the newest observation's time
        uint16 observations;   // observations in [from, now], `from` included
        uint128 minDepth;      // smallest depth at those observations and now
        uint256 maxSegmentGapBps; // largest |segment average - window average| / window average of avg0, in bps
    }

    /// The average over the newest observation that is at least `window` seconds old up to now.
    /// Reverts NotEnoughHistory if there is none.
    function consult(address pair, uint32 window) external view returns (Twap memory t) {
        uint16 n = count[pair];
        uint256 nowTs = block.timestamp;
        // newest first: find the first one at least `window` old
        uint16 k = type(uint16).max;
        for (uint16 i = 0; i < n; i++) {
            if (nowTs >= uint256(observation(pair, i).time) + window) { k = i; break; }
        }
        if (k == type(uint16).max) revert NotEnoughHistory();
        Observation memory start = observation(pair, k);
        (uint256 c0, uint256 c1, uint128 d) = current(pair);
        uint256 span = nowTs - start.time;
        if (span == 0) revert NotEnoughHistory();
        unchecked {
            t.avg0 = (c0 - start.cum0) / span;
            t.avg1 = (c1 - start.cum1) / span;
        }
        t.from = start.time;
        t.newest = n == 0 ? 0 : observation(pair, 0).time;
        t.observations = k + 1;
        (t.minDepth, t.maxSegmentGapBps) = _segments(pair, k, start, Observation(uint64(nowTs), d, c0, c1), t.avg0);
    }

    /// Walks start -> ... -> newest -> now: the smallest depth, and the largest gap of a
    /// segment's average (avg0) from the window's average, in bps.
    function _segments(address pair, uint16 k, Observation memory prev, Observation memory last, uint256 avg)
        private view returns (uint128 minDepth, uint256 maxGapBps)
    {
        minDepth = prev.depth < last.depth ? prev.depth : last.depth;
        for (uint16 j = k + 1; j > 0; j--) {
            Observation memory o = j == 1 ? last : observation(pair, j - 2);
            if (o.depth < minDepth) minDepth = o.depth;
            uint256 dt = uint256(o.time) - prev.time;
            if (dt != 0 && avg != 0) {
                uint256 seg;
                unchecked { seg = (o.cum0 - prev.cum0) / dt; }
                uint256 bps = _mulDiv(seg > avg ? seg - avg : avg - seg, 10_000, avg);
                if (bps > maxGapBps) maxGapBps = bps;
            }
            prev = o;
        }
    }

    function _sqrt(uint256 x) private pure returns (uint256 z) {
        if (x == 0) return 0;
        z = x;
        uint256 y = x / 2 + 1;
        while (y < z) { z = y; y = (x / y + y) / 2; }
    }

    /// floor(a * b / d) with a 512-bit product (Remco Bloemen's mulDiv, MIT).
    function _mulDiv(uint256 a, uint256 b, uint256 d) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(a, b, not(0))
                prod0 := mul(a, b)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }
            if (prod1 == 0) return prod0 / d;
            require(d > prod1, "mulDiv");
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }
            uint256 twos = d & (~d + 1);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            result = prod0 * inv;
        }
    }
}

contracts/UsefulIssuance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// A timelock (ZetaphyTimelock = OpenZeppelin TimelockController) reports its delay.
interface IMinDelay {
    function getMinDelay() external view returns (uint256);
}

/// @title UsefulIssuance: a share of new rewards goes to verified useful work
/// @notice "Security-backed issuance", testnet. It mints NOTHING: it is a RewardVault
///         recipient (`fund()`), so the share of new rewards it receives is set where every
///         other share is (RewardVault.proposeShares: governance + the vault's own 7-day delay).
///         What arrives is split into buckets, one per kind of verified work:
///           - each bucket names a sink contract (UsefulWork scan jobs, BugBounty, a future
///             model-evaluation market) and a share in basis points;
///           - a sink can only PULL (`draw`) what its bucket has accrued, and only when it pays
///             for work its own rules verified (agreement of independent workers, a runner
///             quorum on a bug). Nothing is pushed, so unverified work is never paid;
///           - each bucket has a cap. What would accrue beyond it, and the share no bucket
///             takes (10,000 - sum of bps), goes to `overflow` (e.g. the PoW faucet account
///             or the validators), so rewards are not hoarded when there is little useful work.
///         Every parameter (buckets, caps, overflow, governance itself) is set by `governance`,
///         which must be a timelock whose minimum delay is at least MIN_DELAY: changes are
///         public before they apply. There is no withdraw and no mint.
contract UsefulIssuance {
    uint256 public constant MIN_DELAY = 2 days;
    uint256 public constant MAX_BUCKETS = 6;

    struct Bucket {
        address sink;    // the market that pays verified work (calls draw)
        uint16 bps;      // share of each arrival, out of 10,000
        uint128 cap;     // most this bucket may hold unspent; the rest goes to overflow
        uint128 accrued; // received and not yet drawn
    }

    address public governance;
    address public overflow;
    uint256 public pendingOverflow;
    Bucket[] private _buckets;

    event Funded(address indexed from, uint256 amount);
    event Drawn(address indexed sink, uint256 amount);
    event OverflowPaid(address indexed to, uint256 amount, bool ok);
    event BucketsSet(uint256 count);
    event OverflowSet(address overflow);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotSink();
    error BadBuckets();
    error NotTimelock();
    error ZeroAddress();

    constructor(address governance_, address overflow_) {
        _checkTimelock(governance_);
        if (overflow_ == address(0)) revert ZeroAddress();
        governance = governance_;
        overflow = overflow_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---------------------------------------------------------------- money in

    /// RewardVault pays here (Share.callFund = true); anyone may add more.
    function fund() public payable {
        uint256 amount = msg.value;
        if (amount == 0) return;
        uint256 left = amount;
        for (uint256 i = 0; i < _buckets.length; i++) {
            Bucket storage b = _buckets[i];
            uint256 part = (amount * b.bps) / 10_000;
            left -= part;
            uint256 room = b.cap > b.accrued ? b.cap - b.accrued : 0;
            uint256 keep = part < room ? part : room;
            b.accrued += uint128(keep);
            pendingOverflow += part - keep;
        }
        pendingOverflow += left;
        emit Funded(msg.sender, amount);
    }

    receive() external payable {
        fund();
    }

    // ---------------------------------------------------------------- money out

    /// A sink takes up to `amount` of its bucket to pay work it verified. Returns what it got.
    function draw(uint256 amount) external returns (uint256 paid) {
        uint256 i = _indexOf(msg.sender);
        Bucket storage b = _buckets[i];
        paid = amount < b.accrued ? amount : b.accrued;
        if (paid == 0) return 0;
        b.accrued -= uint128(paid);
        emit Drawn(msg.sender, paid);
        (bool ok, ) = msg.sender.call{value: paid}("");
        if (!ok) revert NotSink(); // a sink that cannot receive is misconfigured: undo
    }

    /// What a sink could draw now.
    function available(address sink) external view returns (uint256) {
        for (uint256 i = 0; i < _buckets.length; i++) if (_buckets[i].sink == sink) return _buckets[i].accrued;
        return 0;
    }

    /// Anyone: pays the overflow out. A recipient that refuses keeps nothing (it stays pending).
    function sweepOverflow() external returns (uint256 amount) {
        amount = pendingOverflow;
        if (amount == 0) return 0;
        pendingOverflow = 0;
        (bool ok, ) = overflow.call{value: amount}("");
        if (!ok) pendingOverflow = amount;
        emit OverflowPaid(overflow, ok ? amount : 0, ok);
    }

    // ---------------------------------------------------------------- governance (timelocked)

    function buckets() external view returns (Bucket[] memory) {
        return _buckets;
    }

    /// Replaces the bucket list. Unspent money of a sink that stays keeps its balance (capped
    /// by the new cap, the excess to overflow); a removed sink's unspent money goes to overflow.
    function setBuckets(Bucket[] calldata next) external onlyGovernance {
        if (next.length > MAX_BUCKETS) revert BadBuckets();
        uint256 total;
        for (uint256 i = 0; i < next.length; i++) {
            if (next[i].sink == address(0) || next[i].bps == 0) revert BadBuckets();
            for (uint256 k = 0; k < i; k++) if (next[k].sink == next[i].sink) revert BadBuckets();
            total += next[i].bps;
        }
        if (total > 10_000) revert BadBuckets();
        uint256 free;
        uint128[] memory carry = new uint128[](next.length);
        for (uint256 i = 0; i < _buckets.length; i++) {
            Bucket memory old = _buckets[i];
            bool kept;
            for (uint256 k = 0; k < next.length; k++) {
                if (next[k].sink == old.sink) {
                    uint128 c = old.accrued < next[k].cap ? old.accrued : next[k].cap;
                    carry[k] = c;
                    free += old.accrued - c;
                    kept = true;
                }
            }
            if (!kept) free += old.accrued;
        }
        delete _buckets;
        for (uint256 i = 0; i < next.length; i++) {
            _buckets.push(Bucket(next[i].sink, next[i].bps, next[i].cap, carry[i]));
        }
        pendingOverflow += free;
        emit BucketsSet(next.length);
    }

    function setOverflow(address next) external onlyGovernance {
        if (next == address(0)) revert ZeroAddress();
        overflow = next;
        emit OverflowSet(next);
    }

    /// The next governance must also be a timelock with at least MIN_DELAY.
    function setGovernance(address next) external onlyGovernance {
        _checkTimelock(next);
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---------------------------------------------------------------- internals

    function _indexOf(address sink) internal view returns (uint256) {
        for (uint256 i = 0; i < _buckets.length; i++) if (_buckets[i].sink == sink) return i;
        revert NotSink();
    }

    function _checkTimelock(address t) internal view {
        if (t.code.length == 0) revert NotTimelock();
        try IMinDelay(t).getMinDelay() returns (uint256 d) {
            if (d < MIN_DELAY) revert NotTimelock();
        } catch {
            revert NotTimelock();
        }
    }
}

contracts/UsefulWork.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IUWReputation {
    function scoreOf(address worker) external view returns (uint256);
    function record(address worker, uint8 kind, bytes32 ref) external;
}

interface IUWIssuance {
    function draw(uint256 amount) external returns (uint256 paid);
}

/// @title UsefulWork: proof of useful work for browsers (Neuro scan jobs)
/// @notice Small Neuro jobs that a web browser can do: a rules scan of one contract's
///         bytecode (zetaphy-neuro's reader in a Web Worker, sourcify and trade simulation
///         off, so the verdict depends only on the code). Unlike NeuroJobs it needs no
///         100 ZETAPHY bond; instead:
///           - Sybil cost: a worker first posts a PoW STAMP (`stamp`): sha256 over the chain
///             id, a recent block's seed, its own address and a nonce must start with
///             `stampBits` zero bits (the same puzzle as the PoW faucet, under another seed
///             so a faucet proof is not a stamp). A stamp buys `stampSeats` seats for
///             `stampLife` seconds, at most `seatsPerDay` a day per address.
///           - Each seat takes a small deposit (`seatDeposit`), returned when the worker's
///             answer is accepted, kept (into the subsidy reserve) when it is not.
///           - Redundancy: every job has `seats` (2..5) independent seats and pays only
///             answers that at least `quorum` seats agree on. Answers are commit-reveal
///             (keccak(verdict, worker, salt, jobId)), so nobody can copy another's answer.
///           - Canaries: a feeder (an address governance trusts to post jobs, e.g. the Neuro
///             watch-list Action) can post a known-answer job with a hidden commitment to the
///             right verdict. After the commits close it reveals it; seats that answered
///             otherwise are slashed even when they agreed with each other.
///           - Reputation (WorkerReputation): every settled seat is recorded. A job may ask
///             a minimum score (`minScore`), and during the first `priorityWindow` seconds
///             only workers with at least `priorityScore` may take seats, so important
///             jobs go to proven workers first.
///         Rewards: the poster's fee is split among the agreeing seats; feeder jobs marked
///         `subsidized` also pay `subsidy` per agreeing seat, from the forfeited deposits
///         and then from UsefulIssuance (a RewardVault share). No new minting.
///         Results are signed by being transactions of the worker's own key; the accepted
///         verdict is on-chain (`getJob(id).result`).
contract UsefulWork {
    // WorkerReputation.Kind
    uint8 internal constant AGREED = 0;
    uint8 internal constant DISAGREED = 1;
    uint8 internal constant MISSED = 2;
    uint8 internal constant SLASHED = 3;

    struct Params {
        uint8 stampBits;        // leading zero bits a stamp needs (8..48)
        uint16 stampSeats;      // seats one stamp buys
        uint32 stampLife;       // seconds a stamp's seats stay usable
        uint16 seatsPerDay;     // most seats one address takes per UTC day
        uint8 seats;            // seats per job (2..5)
        uint8 quorum;           // agreeing seats needed (> seats/2)
        uint32 commitWindow;    // seconds seats can be taken
        uint32 revealWindow;    // seconds to reveal after the commits close
        uint128 seatDeposit;    // per seat, returned on an accepted answer
        uint128 subsidy;        // per agreeing seat of a subsidized job
        uint16 priorityScore;   // score needed during the priority window (0 = none)
        uint32 priorityWindow;  // seconds after posting reserved for proven workers
    }

    struct Job {
        address poster;
        uint64 createdAt;
        uint64 closedAt;        // when the seats filled (0: closes at createdAt + commitWindow)
        uint32 commitWindow;
        uint32 revealWindow;
        uint8 seats;
        uint8 quorum;
        uint8 taken;
        uint8 revealed;
        bool subsidized;
        bool settled;
        bool canaryRevealed;
        uint16 minScore;
        uint128 fee;
        uint128 deposit;
        bytes32 chain;          // Neuro chain key, e.g. "zetaphy", "bsc"
        bytes32 codeHash;       // keccak256 of the runtime bytecode the poster saw
        bytes32 canary;         // keccak(verdict, salt, jobId) of the known answer, or 0
        bytes32 canaryVerdict;
        bytes32 result;         // the accepted verdict (0 = none)
        string target;          // the contract address on that chain
    }

    struct Credit {
        uint32 seats;
        uint64 until;
    }

    address public governance;
    IUWReputation public reputation;
    IUWIssuance public issuance;
    Params public params;
    uint256 public reserve;              // forfeited deposits + fund(): pays subsidies first
    mapping(address => bool) public feeders;
    mapping(address => Credit) public credits;
    mapping(bytes32 => bool) public usedStamp;
    mapping(address => mapping(uint256 => uint256)) public seatsOnDay;
    mapping(address => uint256) public owed;
    /// Stamps, new jobs and new seats stop while paused (reveals, canaries, settling and withdrawals go
    /// on, so no deposit is stuck). `zetaphy deploy-useful-work` deploys it paused; governance opens it.
    bool public paused;
    address public guardian;             // may pause (never unpause): a fast brake for governance

    Job[] private _jobs;
    mapping(uint256 => address[]) private _seats;
    mapping(uint256 => mapping(address => bytes32)) public commitments;
    mapping(uint256 => mapping(address => bytes32)) public verdicts;

    event Funded(address indexed from, uint256 amount);
    event Stamped(address indexed worker, bytes32 stamp, uint32 seats, uint64 until);
    event Posted(uint256 indexed id, address indexed poster, bytes32 indexed chain, string target, bytes32 codeHash, uint256 fee, bool subsidized, bool canary);
    event Committed(uint256 indexed id, address indexed worker);
    event Revealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event CanaryRevealed(uint256 indexed id, bytes32 verdict);
    event Settled(uint256 indexed id, bytes32 result, uint256 agreed, uint256 paidEach);
    event SeatOutcome(uint256 indexed id, address indexed worker, uint8 kind);
    event ParamsSet();
    event FeederSet(address indexed feeder, bool on);
    event Withdrawn(address indexed to, uint256 amount);
    event PausedSet(bool paused);
    event GuardianSet(address guardian);
    event GovernanceSet(address governance);

    error Paused();
    error NotGovernance();
    error NotFeeder();
    error BadParams();
    error BadValue();
    error BadJob();
    error StampTooOld();
    error StampUsed();
    error StampWeak();
    error NoCredit();
    error DayFull();
    error LowScore();
    error Closed();
    error AlreadyIn();
    error NotSeated();
    error TooEarly();
    error BadReveal();
    error Nothing();

    constructor(address governance_, IUWReputation reputation_, IUWIssuance issuance_, Params memory p) {
        governance = governance_;
        reputation = reputation_;
        issuance = issuance_;
        _setParams(p);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    receive() external payable {
        fund();
    }

    /// Adds to the subsidy reserve (anyone; RewardVault can pay here directly too).
    function fund() public payable {
        reserve += msg.value;
        emit Funded(msg.sender, msg.value);
    }

    // ---------------------------------------------------------------- stamp (PoW)

    /// The 32 bytes the stamp hashes in place of a block hash: keccak(blockhash(height), this).
    function stampSeed(uint256 height) public view returns (bytes32) {
        bytes32 bh = blockhash(height);
        if (bh == bytes32(0)) return bytes32(0);
        return keccak256(abi.encodePacked(bh, address(this)));
    }

    /// sha256(chainId u64 BE || seed || worker || nonce u64 BE): the PoW faucet's layout.
    function stampHash(address worker, uint256 height, uint64 nonce) public view returns (bytes32) {
        return sha256(abi.encodePacked(uint64(block.chainid), stampSeed(height), worker, nonce));
    }

    function stamp(uint256 height, uint64 nonce) external {
        if (paused) revert Paused();
        if (height >= block.number || block.number - height > 256 || stampSeed(height) == bytes32(0)) revert StampTooOld();
        bytes32 h = stampHash(msg.sender, height, nonce);
        if (usedStamp[h]) revert StampUsed();
        if (uint256(h) >> (256 - params.stampBits) != 0) revert StampWeak();
        usedStamp[h] = true;
        Credit storage c = credits[msg.sender];
        if (c.until < block.timestamp) c.seats = 0;
        c.seats += params.stampSeats;
        c.until = uint64(block.timestamp + params.stampLife);
        emit Stamped(msg.sender, h, c.seats, c.until);
    }

    // ---------------------------------------------------------------- posting

    /// Anyone posts a scan job and pays the fee the agreeing seats share.
    function post(bytes32 chain, string calldata target, bytes32 codeHash, uint16 minScore) external payable returns (uint256) {
        if (msg.value == 0) revert BadValue();
        return _post(chain, target, codeHash, minScore, false, bytes32(0));
    }

    /// A feeder posts a job that may be subsidized and may carry a hidden known answer.
    function postFeeder(bytes32 chain, string calldata target, bytes32 codeHash, uint16 minScore, bool subsidized, bytes32 canary)
        external payable returns (uint256)
    {
        if (!feeders[msg.sender]) revert NotFeeder();
        return _post(chain, target, codeHash, minScore, subsidized, canary);
    }

    function _post(bytes32 chain, string calldata target, bytes32 codeHash, uint16 minScore, bool subsidized, bytes32 canary)
        internal returns (uint256 id)
    {
        if (paused) revert Paused();
        if (chain == bytes32(0) || codeHash == bytes32(0) || bytes(target).length == 0 || bytes(target).length > 128) revert BadJob();
        Params memory p = params;
        id = _jobs.length;
        Job storage j = _jobs.push();
        j.poster = msg.sender;
        j.createdAt = uint64(block.timestamp);
        j.commitWindow = p.commitWindow;
        j.revealWindow = p.revealWindow;
        j.seats = p.seats;
        j.quorum = p.quorum;
        j.subsidized = subsidized;
        j.minScore = minScore;
        j.fee = uint128(msg.value);
        j.deposit = p.seatDeposit;
        j.chain = chain;
        j.codeHash = codeHash;
        j.canary = canary;
        j.target = target;
        emit Posted(id, msg.sender, chain, target, codeHash, msg.value, subsidized, canary != bytes32(0));
    }

    // ---------------------------------------------------------------- commit / reveal

    function commitmentOf(bytes32 verdict, address worker, bytes32 salt, uint256 id) public pure returns (bytes32) {
        return keccak256(abi.encode(verdict, worker, salt, id));
    }

    function commit(uint256 id, bytes32 commitment) external payable {
        if (msg.value != _job(id).deposit) revert BadValue();
        _commit(id, commitment);
    }

    /// Several seats in one transaction (one wallet prompt in the browser).
    function commitMany(uint256[] calldata ids, bytes32[] calldata cs) external payable {
        if (ids.length != cs.length) revert BadValue();
        uint256 total;
        for (uint256 i = 0; i < ids.length; i++) {
            total += _job(ids[i]).deposit;
            _commit(ids[i], cs[i]);
        }
        if (msg.value != total) revert BadValue();
    }

    function _commit(uint256 id, bytes32 commitment) internal {
        if (paused) revert Paused();
        Job storage j = _jobs[id];
        if (j.settled || j.taken >= j.seats || block.timestamp >= _closeTime(j)) revert Closed();
        if (commitments[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        if (commitment == bytes32(0)) revert BadValue();
        Credit storage c = credits[msg.sender];
        if (c.seats == 0 || c.until < block.timestamp) revert NoCredit();
        uint256 day = block.timestamp / 1 days;
        if (seatsOnDay[msg.sender][day] >= params.seatsPerDay) revert DayFull();
        if (address(reputation) != address(0)) {
            uint256 score = reputation.scoreOf(msg.sender);
            if (score < j.minScore) revert LowScore();
            if (block.timestamp < j.createdAt + params.priorityWindow && score < params.priorityScore) revert LowScore();
        }
        c.seats--;
        seatsOnDay[msg.sender][day]++;
        commitments[id][msg.sender] = commitment;
        _seats[id].push(msg.sender);
        j.taken++;
        if (j.taken == j.seats) j.closedAt = uint64(block.timestamp);
        emit Committed(id, msg.sender);
    }

    function reveal(uint256 id, bytes32 verdict, bytes32 salt) external {
        _reveal(id, verdict, salt);
    }

    function revealMany(uint256[] calldata ids, bytes32[] calldata vs, bytes32[] calldata salts) external {
        if (ids.length != vs.length || ids.length != salts.length) revert BadValue();
        for (uint256 i = 0; i < ids.length; i++) _reveal(ids[i], vs[i], salts[i]);
    }

    function _reveal(uint256 id, bytes32 verdict, bytes32 salt) internal {
        Job storage j = _job(id);
        if (j.settled) revert Closed();
        if (!_commitsClosed(j)) revert TooEarly();
        if (block.timestamp >= _closeTime(j) + j.revealWindow) revert Closed();
        bytes32 c = commitments[id][msg.sender];
        if (c == bytes32(0)) revert NotSeated();
        if (verdicts[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        if (verdict == bytes32(0) || commitmentOf(verdict, msg.sender, salt, id) != c) revert BadReveal();
        verdicts[id][msg.sender] = verdict;
        j.revealed++;
        emit Revealed(id, msg.sender, verdict);
    }

    /// The feeder reveals a canary's known answer once nobody can commit any more.
    function revealCanary(uint256 id, bytes32 verdict, bytes32 salt) external {
        Job storage j = _job(id);
        if (msg.sender != j.poster) revert NotFeeder();
        if (j.settled || j.canary == bytes32(0) || j.canaryRevealed) revert Closed();
        if (!_commitsClosed(j)) revert TooEarly();
        if (keccak256(abi.encode(verdict, salt, id)) != j.canary) revert BadReveal();
        j.canaryVerdict = verdict;
        j.canaryRevealed = true;
        emit CanaryRevealed(id, verdict);
    }

    // ---------------------------------------------------------------- settle

    /// Anyone, once every seat revealed (and the canary, if any) or the reveal window ended.
    function settle(uint256 id) external {
        Job storage j = _job(id);
        if (j.settled) revert Closed();
        bool allIn = _commitsClosed(j) && j.taken == j.seats && j.revealed == j.taken && (j.canary == bytes32(0) || j.canaryRevealed);
        if (!allIn && block.timestamp < _closeTime(j) + j.revealWindow) revert TooEarly();
        j.settled = true;
        address[] memory seats = _seats[id];
        bytes32 accepted;
        bool canary = j.canaryRevealed;
        if (canary) accepted = j.canaryVerdict;
        else accepted = _majority(id, seats, j.quorum);
        j.result = accepted;

        uint256 agreed;
        for (uint256 i = 0; i < seats.length; i++) if (accepted != bytes32(0) && verdicts[id][seats[i]] == accepted) agreed++;

        // the pot of the agreeing seats: the fee, plus the subsidy of a subsidized job
        uint256 pot;
        if (agreed > 0) {
            pot = j.fee;
            if (j.subsidized) pot += _subsidy(params.subsidy * agreed);
        } else if (j.fee > 0) {
            owed[j.poster] += j.fee; // nobody agreed: the poster gets the fee back
        }
        uint256 each = agreed > 0 ? pot / agreed : 0;
        reserve += agreed > 0 ? pot - each * agreed : 0;
        for (uint256 i = 0; i < seats.length; i++) _judgeSeat(id, seats[i], accepted, canary, j.deposit, each);
        emit Settled(id, accepted, agreed, each);
    }

    function _judgeSeat(uint256 id, address w, bytes32 accepted, bool canary, uint256 deposit, uint256 each) internal {
        bytes32 v = verdicts[id][w];
        uint8 kind;
        if (v == bytes32(0)) {
            kind = MISSED;
            reserve += deposit;
        } else if (accepted == bytes32(0)) {
            owed[w] += deposit; // no accepted answer: nobody is judged
            emit SeatOutcome(id, w, 255);
            return;
        } else if (v == accepted) {
            kind = AGREED;
            owed[w] += deposit + each;
        } else {
            kind = canary ? SLASHED : DISAGREED;
            reserve += deposit;
        }
        emit SeatOutcome(id, w, kind);
        if (address(reputation) != address(0)) {
            try reputation.record(w, kind, bytes32(id)) {} catch {}
        }
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: a}("");
        if (!ok) revert Nothing();
        emit Withdrawn(msg.sender, a);
    }

    // ---------------------------------------------------------------- governance

    function setParams(Params calldata p) external onlyGovernance {
        _setParams(p);
    }

    function setFeeder(address f, bool on) external onlyGovernance {
        feeders[f] = on;
        emit FeederSet(f, on);
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
        emit GovernanceSet(next);
    }

    /// Governance pauses or unpauses; the guardian may only pause.
    function setPaused(bool p) external {
        if (msg.sender != governance && !(p && msg.sender == guardian && guardian != address(0))) revert NotGovernance();
        paused = p;
        emit PausedSet(p);
    }

    function setGuardian(address g) external onlyGovernance {
        guardian = g;
        emit GuardianSet(g);
    }

    function _setParams(Params memory p) internal {
        if (p.stampBits < 8 || p.stampBits > 48 || p.stampSeats == 0 || p.stampLife == 0 || p.seatsPerDay == 0) revert BadParams();
        if (p.seats < 2 || p.seats > 5 || p.quorum * 2 <= p.seats || p.quorum > p.seats) revert BadParams();
        if (p.commitWindow == 0 || p.revealWindow == 0 || p.priorityWindow >= p.commitWindow) revert BadParams();
        params = p;
        emit ParamsSet();
    }

    // ---------------------------------------------------------------- reads

    function jobCount() external view returns (uint256) {
        return _jobs.length;
    }

    function getJob(uint256 id) external view returns (Job memory) {
        return _job(id);
    }

    function seatsOf(uint256 id) external view returns (address[] memory) {
        return _seats[id];
    }

    /// Up to `max` job ids from `from` on that still take seats now.
    function openJobs(uint256 from, uint256 max) external view returns (uint256[] memory ids) {
        uint256[] memory buf = new uint256[](max);
        uint256 n;
        for (uint256 i = from; i < _jobs.length && n < max; i++) {
            Job storage j = _jobs[i];
            if (!j.settled && j.taken < j.seats && block.timestamp < _closeTime(j)) buf[n++] = i;
        }
        ids = new uint256[](n);
        for (uint256 i = 0; i < n; i++) ids[i] = buf[i];
    }

    /// Phase of a job: 0 taking seats, 1 revealing, 2 ready to settle, 3 settled.
    function phase(uint256 id) external view returns (uint8) {
        Job storage j = _job(id);
        if (j.settled) return 3;
        if (!_commitsClosed(j)) return 0;
        bool allIn = j.taken == j.seats && j.revealed == j.taken && (j.canary == bytes32(0) || j.canaryRevealed);
        if (allIn || block.timestamp >= _closeTime(j) + j.revealWindow) return 2;
        return 1;
    }

    // ---------------------------------------------------------------- internals

    function _job(uint256 id) internal view returns (Job storage) {
        if (id >= _jobs.length) revert BadJob();
        return _jobs[id];
    }

    function _closeTime(Job storage j) internal view returns (uint256) {
        return j.closedAt != 0 ? j.closedAt : uint256(j.createdAt) + j.commitWindow;
    }

    function _commitsClosed(Job storage j) internal view returns (bool) {
        return j.taken == j.seats || block.timestamp >= _closeTime(j);
    }

    function _majority(uint256 id, address[] memory seats, uint8 quorum) internal view returns (bytes32) {
        for (uint256 i = 0; i < seats.length; i++) {
            bytes32 v = verdicts[id][seats[i]];
            if (v == bytes32(0)) continue;
            uint256 n;
            for (uint256 k = 0; k < seats.length; k++) if (verdicts[id][seats[k]] == v) n++;
            if (n >= quorum) return v; // quorum > seats/2: at most one verdict can reach it
        }
        return bytes32(0);
    }

    /// Takes up to `want` from the reserve, then from UsefulIssuance. Returns what it got.
    function _subsidy(uint256 want) internal returns (uint256 got) {
        if (want == 0) return 0;
        got = want < reserve ? want : reserve;
        reserve -= got;
        if (got < want && address(issuance) != address(0)) {
            uint256 before = address(this).balance;
            try issuance.draw(want - got) returns (uint256) {} catch {}
            uint256 arrived = address(this).balance - before;
            // draw() pays through receive(), which counts it into the reserve: move it out again
            reserve -= arrived;
            got += arrived;
        }
    }
}

contracts/VaultTestRecipients.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Test-only recipients for RewardVault.

/// Refuses every payment.
contract RefusingRecipient {
    receive() external payable { revert("no"); }
}

interface IVault {
    function applyShares() external;
    function release() external returns (uint256);
}

/// Tries to re-enter the vault while being paid.
contract ReentrantRecipient {
    IVault public vault;
    uint256 public attempts;
    function setVault(address v) external { vault = IVault(v); }
    receive() external payable {
        attempts += 1;
        try vault.applyShares() {} catch {}
        try vault.release() {} catch {}
    }
}

contracts/VulnerableVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title VulnerableVault: a DELIBERATELY VULNERABLE contract for the bug-hunting prototype
/// @notice TEST ONLY. Never deploy it with anything of value. It is the target of the first
///         BugBounty on the testnet (zetaphy-hub/bounties/vulnerable-vault.json), so that the
///         browser fuzzer, the commit-reveal of findings and the runners' verification can be
///         shown end to end on a bug that really exists.
///
///         The bug: `initialize()` was meant to run once, from the deployment script, but the
///         deployment never calls it and it has no access control. Whoever calls it first
///         becomes the owner and can `sweep` every depositor's money.
contract VulnerableVault {
    address public owner;
    mapping(address => uint256) public balances;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw(uint256 amount) external {
        require(balances[msg.sender] >= amount, "balance");
        balances[msg.sender] -= amount;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "send");
    }

    /// BUG (deliberate): anyone may call this while no owner is set.
    function initialize() external {
        require(owner == address(0), "done");
        owner = msg.sender;
    }

    function sweep(address to) external {
        require(msg.sender == owner, "owner");
        (bool ok, ) = to.call{value: address(this).balance}("");
        require(ok, "send");
    }
}

contracts/WebAuthnVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title WebAuthnVerifier: checks a passkey (WebAuthn) assertion on chain
/// @notice Stateless helper shared by LabelRegistry (human labels) and
///         AgentPolicyWallet (emergency freeze by the owner's passkey).
///         The P-256 (secp256r1) signature is checked by the precompile at
///         0x…0100 that cosmos/evm ships (RIP-7212 interface: input
///         hash ‖ r ‖ s ‖ x ‖ y, output 32 bytes = 1 when valid, empty
///         otherwise). ZETAPHY's genesis enables it (active_static_precompiles
///         in zetaphy-chain/setup-node.sh).
///
///         What is checked, as a relying party would (WebAuthn §7.2):
///           - clientDataJSON has "type":"webauthn.get" and
///             "challenge":"<base64url of the 32-byte challenge>";
///           - authenticatorData starts with rpIdHash (sha256 of the site's
///             host name; 0 = any site) and has the user-present flag, and
///             the user-verified flag when requireUV;
///           - the signature is over sha256(authenticatorData ‖ sha256(clientDataJSON)).
///         Not checked: the origin inside clientDataJSON (rpIdHash already
///         binds the site), the signature counter (passkeys that sync keep it
///         at 0), and attestation (who made the authenticator).
contract WebAuthnVerifier {
    address public constant P256 = 0x0000000000000000000000000000000000000100;

    bytes1 private constant FLAG_UP = 0x01;
    bytes1 private constant FLAG_UV = 0x04;

    /// A passkey's answer to navigator.credentials.get(): the authenticator
    /// data, the client data JSON and the signature as (r, s).
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    /// True when `a` is a valid assertion of the passkey (x, y) over `challenge`.
    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool)
    {
        if (!_flagsOk(a.authenticatorData, rpIdHash, requireUV)) return false;
        if (!_contains(a.clientDataJSON, bytes('"type":"webauthn.get"'))) return false;
        if (!_contains(a.clientDataJSON, abi.encodePacked('"challenge":"', base64url(challenge), '"'))) return false;
        bytes32 h = sha256(abi.encodePacked(a.authenticatorData, sha256(a.clientDataJSON)));
        (bool ok, bytes memory ret) = P256.staticcall(abi.encode(h, a.r, a.s, x, y));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _flagsOk(bytes calldata authData, bytes32 rpIdHash, bool requireUV) private pure returns (bool) {
        if (authData.length < 37) return false;
        if (rpIdHash != bytes32(0) && bytes32(authData[0:32]) != rpIdHash) return false;
        bytes1 flags = authData[32];
        if (flags & FLAG_UP == 0) return false;
        if (requireUV && flags & FLAG_UV == 0) return false;
        return true;
    }

    /// base64url without padding of 32 bytes (43 characters), as WebAuthn
    /// writes the challenge in clientDataJSON.
    function base64url(bytes32 data) public pure returns (string memory) {
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
        bytes memory out = new bytes(43);
        uint256 v = uint256(data);
        // 32 bytes = 256 bits = 42 full 6-bit groups + 4 bits (padded with 2 zero bits)
        for (uint256 i = 0; i < 42; i++) {
            out[i] = table[(v >> (250 - 6 * i)) & 63];
        }
        out[42] = table[(v & 15) << 2];
        return string(out);
    }

    function _contains(bytes calldata hay, bytes memory needle) private pure returns (bool) {
        uint256 n = needle.length;
        if (hay.length < n) return false;
        bytes32 nh = keccak256(needle);
        for (uint256 i = 0; i + n <= hay.length; i++) {
            if (hay[i] == needle[0] && keccak256(hay[i:i + n]) == nh) return true;
        }
        return false;
    }
}

contracts/WorkerReputation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// NeuroJobs' runner record (read-only; the runner's NeuroJobs history counts too).
interface IRepRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// The identity registry (NeuroIdentity, ERC-8004 Identity Registry) a worker may link.
interface IRepIdentity {
    function ownerOf(uint256 tokenId) external view returns (address);
}

/// @title WorkerReputation: on-chain track record of useful-work workers and Neuro runners
/// @notice An ERC-8004-style Reputation Registry for the workers of ZETAPHY's useful-work
///         markets (UsefulWork scan jobs, BugBounty findings) and, read-only, the bonded
///         NeuroJobs runners. Feedback is NOT free text from anyone: only contracts that
///         governance names as reporters (the markets themselves) write outcomes, and each
///         outcome is the result of a commit-reveal round they settled on-chain:
///           - agreed:     the worker's revealed answer matched the accepted result
///           - disagreed:  it revealed a different answer
///           - missed:     it took a seat and never revealed
///           - slashed:    it answered a known-answer (canary) job wrong, or governance slashed it
///           - bugValid / bugInvalid: a bug finding runners accepted / rejected
///         The score (0..1000) is a smoothed success rate:
///             good = agreed + 3*bugValid + NeuroJobs.agreed
///             bad  = disagreed + 2*missed + 5*slashed + 3*bugInvalid + NeuroJobs.rejected
///             score = 1000 * good / (good + bad + PRIOR)
///         PRIOR (5 phantom failures) means a new address starts at 0 and needs a track
///         record before the markets give it important jobs (UsefulWork.minScore). A score
///         is only as good as the markets that feed it: it measures agreement with the
///         other workers (and canaries), not truth.
///
///         Linking: a worker that owns an ERC-8004 agent in NeuroIdentity can link it, and
///         `getSummary(agentId)` then answers in the ERC-8004 reputation shape (count,
///         average 0..100).
///
///         Governance (a ZetaphyTimelock) names reporters and may slash by hand; adding a
///         reporter is a timelocked action, removing one is too (no guardian path: a
///         reporter can only lower or raise scores, it cannot move funds).
contract WorkerReputation {
    uint256 public constant PRIOR = 5;
    uint256 public constant MAX_SCORE = 1000;

    enum Kind { Agreed, Disagreed, Missed, Slashed, BugValid, BugInvalid }

    struct Record {
        uint32 agreed;
        uint32 disagreed;
        uint32 missed;
        uint32 slashed;
        uint32 bugValid;
        uint32 bugInvalid;
        uint64 lastAt;
    }

    address public governance;
    IRepRunners public immutable runners;   // NeuroJobs, or address(0)
    IRepIdentity public immutable identity; // NeuroIdentity, or address(0)
    mapping(address => bool) public reporters;
    mapping(address => Record) private _records;
    mapping(uint256 => address) public workerOfAgent;
    mapping(address => uint256) public agentOfWorker; // 0 = none (agent ids start at 1 in NeuroIdentity)

    event Outcome(address indexed worker, Kind indexed kind, address indexed reporter, bytes32 ref);
    event ReporterSet(address indexed reporter, bool on);
    event AgentLinked(address indexed worker, uint256 indexed agentId);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotReporter();
    error NotAgentOwner();
    error ZeroAddress();

    constructor(address governance_, IRepRunners runners_, IRepIdentity identity_) {
        if (governance_ == address(0)) revert ZeroAddress();
        governance = governance_;
        runners = runners_;
        identity = identity_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---------------------------------------------------------------- writes

    /// A market reports one settled outcome for a worker (ref = the job / finding it was about).
    function record(address worker, Kind kind, bytes32 ref) external {
        if (!reporters[msg.sender]) revert NotReporter();
        _record(worker, kind, ref);
    }

    /// Governance slashes by hand (e.g. proven collusion found off-chain).
    function slash(address worker, bytes32 ref) external onlyGovernance {
        _record(worker, Kind.Slashed, ref);
    }

    function _record(address worker, Kind kind, bytes32 ref) internal {
        Record storage r = _records[worker];
        if (kind == Kind.Agreed) r.agreed++;
        else if (kind == Kind.Disagreed) r.disagreed++;
        else if (kind == Kind.Missed) r.missed++;
        else if (kind == Kind.Slashed) r.slashed++;
        else if (kind == Kind.BugValid) r.bugValid++;
        else r.bugInvalid++;
        r.lastAt = uint64(block.timestamp);
        emit Outcome(worker, kind, msg.sender, ref);
    }

    function setReporter(address reporter, bool on) external onlyGovernance {
        if (reporter == address(0)) revert ZeroAddress();
        reporters[reporter] = on;
        emit ReporterSet(reporter, on);
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert ZeroAddress();
        governance = next;
        emit GovernanceChanged(next);
    }

    /// Links the caller to an ERC-8004 agent it owns (one agent per worker, one worker per agent).
    function linkAgent(uint256 agentId) external {
        if (address(identity) == address(0) || identity.ownerOf(agentId) != msg.sender) revert NotAgentOwner();
        uint256 old = agentOfWorker[msg.sender];
        if (old != 0) delete workerOfAgent[old];
        address prev = workerOfAgent[agentId];
        if (prev != address(0)) delete agentOfWorker[prev];
        workerOfAgent[agentId] = msg.sender;
        agentOfWorker[msg.sender] = agentId;
        emit AgentLinked(msg.sender, agentId);
    }

    // ---------------------------------------------------------------- reads

    function recordOf(address worker) external view returns (Record memory) {
        return _records[worker];
    }

    /// Good and bad outcome weights (this registry's records plus the NeuroJobs runner record).
    function weights(address worker) public view returns (uint256 good, uint256 bad) {
        Record memory r = _records[worker];
        good = uint256(r.agreed) + 3 * uint256(r.bugValid);
        bad = uint256(r.disagreed) + 2 * uint256(r.missed) + 5 * uint256(r.slashed) + 3 * uint256(r.bugInvalid);
        if (address(runners) != address(0)) {
            try runners.workers(worker) returns (uint128, uint64, bool, uint32 agreed, uint32 rejected) {
                good += agreed;
                bad += rejected;
            } catch {}
        }
    }

    /// 0..1000; 0 for an address with no record.
    function scoreOf(address worker) public view returns (uint256) {
        (uint256 good, uint256 bad) = weights(worker);
        return (MAX_SCORE * good) / (good + bad + PRIOR);
    }

    /// ERC-8004 reputation shape for a linked agent: (outcomes counted, average 0..100).
    function getSummary(uint256 agentId) external view returns (uint64 count, uint8 averageScore) {
        address w = workerOfAgent[agentId];
        if (w == address(0)) return (0, 0);
        (uint256 good, uint256 bad) = weights(w);
        count = uint64(good + bad);
        averageScore = uint8(scoreOf(w) / 10);
    }
}

contracts/ZetaphyBridgeInbox.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// StarkLightClient as the inbox reads it.
interface IZetaphyLightClient {
    /// The final app hash of ZETAPHY block `height` (reverts when unknown or the client is frozen).
    function appHashAt(uint64 height) external view returns (bytes32);
}

interface IERC20Release {
    function transfer(address to, uint256 v) external returns (bool);
}

/// @title ZetaphyBridgeInbox: releases tokens on Ethereum for messages proven from ZETAPHY's state
/// @notice No relayer or multisig is trusted for WHAT is released: a message is accepted only with
///         a chain of proofs, all checked here or in the light client:
///           1. app_hash of a final ZETAPHY header (StarkLightClient: STARK over the validator set);
///           2. the evm store's root in app_hash: Cosmos SDK multistore, ICS23 Tendermint-spec ops;
///           3. ZetaphyOutbox's storage slot 0 in the evm store: ICS23 IAVL-spec existence proof of
///              key 0x02 || outbox || 0x00..00 (cosmos/evm x/vm KeyPrefixStorage) with the 32-byte root;
///           4. the message leaf in the outbox tree (32 SHA-256 siblings) and the tree's count.
///         Then: the sender is ZETAPHY's lockbox, the destination is this chain and this contract,
///         and the nonce was never consumed (replay protection).
///         Circuit breaker in the style of BridgeGuard: a daily release limit; guardians pause and
///         lower the limit at once (they only reduce risk); governance unpauses and raises the limit,
///         at most x2 per step, each raise LIMIT_DELAY after it was proposed. Governance cannot
///         release anything: it can delay releases, never forge them. A release over the limit or
///         while paused reverts and can simply be retried later (anyone may submit it).
///         Testnet prototype, not audited. See docs/future/trustless-bridge.md.
contract ZetaphyBridgeInbox {
    struct InnerOp {
        bytes prefix;
        bytes suffix;
    }

    /// Proof that the outbox root is in ZETAPHY's state at a header's app_hash.
    struct StateProof {
        bytes32 outboxRoot;        // value of the outbox's slot 0
        bytes iavlLeafPrefix;      // zz(0) zz(1) zz(version)
        InnerOp[] iavlPath;        // evm store, leaf to root (IavlSpec)
        InnerOp[] storePath;       // multistore, evm store root to app hash (TendermintSpec)
    }

    struct Message {
        uint64 nonce;
        address sender;
        uint256 dstChainId;
        address receiver;
        bytes payload;             // abi.encode(recipient, amount)
    }

    bytes32 public constant LEAF_TAG = keccak256("zetaphy/outbox/v1");
    uint64 public constant LIMIT_DELAY = 7 days;

    IZetaphyLightClient public immutable lightClient;
    uint256 public immutable zetaphyChainId;  // ZETAPHY's EVM chain id (in every leaf)
    address public immutable zetaphyOutbox;
    address public immutable zetaphySender;   // the ZETAPHY lockbox allowed to release tokens here
    IERC20Release public immutable token;

    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;
    uint256 public dailyLimit;
    uint256 public pendingLimit;
    uint64 public pendingAt;
    uint256 public releasedToday;
    uint64 public day;
    mapping(uint64 => bool) public consumed;

    event Released(uint64 indexed nonce, address indexed recipient, uint256 amount, uint64 height);
    event Paused(address by);
    event Unpaused();
    event LimitSet(uint256 limit);
    event LimitProposed(uint256 limit, uint64 at);
    event GuardianSet(address who, bool on);

    error AlreadyConsumed();
    error BadStateProof(uint256 step);
    error BadMessage();
    error BridgePaused();
    error OverLimit(uint256 left);
    error NotGovernance();
    error NotGuardian();
    error TooEarly();

    constructor(IZetaphyLightClient lc, uint256 zetaphyChainId_, address outbox, address sender, IERC20Release token_, address governance_, address guardian_, uint256 dailyLimit_) {
        lightClient = lc;
        zetaphyChainId = zetaphyChainId_;
        zetaphyOutbox = outbox;
        zetaphySender = sender;
        token = token_;
        governance = governance_;
        if (guardian_ != address(0)) { guardian[guardian_] = true; emit GuardianSet(guardian_, true); }
        dailyLimit = dailyLimit_;
        emit LimitSet(dailyLimit_);
    }

    // ------------------------------------------------------------------ release

    /// Anyone: release the tokens of message `m`, proven at ZETAPHY block `height` (whose app_hash is
    /// the state after block height - 1, so a lock in block h is provable with any final header > h).
    function release(uint64 height, StateProof calldata sp, Message calldata m, bytes32[32] calldata siblings, uint64 count) external {
        if (consumed[m.nonce]) revert AlreadyConsumed();
        if (m.sender != zetaphySender || m.dstChainId != block.chainid || m.receiver != address(this)) revert BadMessage();
        bytes32 app = lightClient.appHashAt(height);
        bytes32 evmRoot = iavlRoot(abi.encodePacked(uint8(2), zetaphyOutbox, bytes32(0)), sp.outboxRoot, sp.iavlLeafPrefix, sp.iavlPath);
        if (storeRoot("evm", evmRoot, sp.storePath) != app) revert BadStateProof(2);
        bytes32 leaf = sha256(abi.encode(LEAF_TAG, zetaphyChainId, zetaphyOutbox, m.nonce, m.sender, m.dstChainId, m.receiver, sha256(m.payload)));
        if (m.nonce >= count || outboxRoot(leaf, m.nonce, siblings, count) != sp.outboxRoot) revert BadStateProof(4);
        consumed[m.nonce] = true;
        (address recipient, uint256 amount) = abi.decode(m.payload, (address, uint256));
        _spend(amount);
        require(token.transfer(recipient, amount), "transfer");
        emit Released(m.nonce, recipient, amount, height);
    }

    function _spend(uint256 amount) private {
        if (paused) revert BridgePaused();
        uint64 today = uint64(block.timestamp / 1 days);
        if (day != today) { day = today; releasedToday = 0; }
        uint256 used = releasedToday;
        if (used + amount > dailyLimit) revert OverLimit(dailyLimit > used ? dailyLimit - used : 0);
        releasedToday = used + amount;
    }

    // ------------------------------------------------------------------ proofs (pure, reusable)

    /// The outbox root for a leaf at `index` with its 32 siblings and the tree's count.
    function outboxRoot(bytes32 leaf, uint64 index, bytes32[32] calldata sib, uint64 count) public pure returns (bytes32) {
        bytes32 node = leaf;
        for (uint256 h = 0; h < 32; h++) {
            node = (index >> h) & 1 == 1 ? sha256(abi.encodePacked(sib[h], node)) : sha256(abi.encodePacked(node, sib[h]));
        }
        return sha256(abi.encodePacked(node, uint256(count)));
    }

    /// ICS23 IavlSpec existence proof: the IAVL root for (key, 32-byte value). Leaf and inner
    /// prefixes are checked as ics23 does (validateIavlOps, InnerSpec lengths, no leaf prefix on an
    /// inner node), so an inner node can never be passed off as a leaf or the other way round.
    function iavlRoot(bytes memory key, bytes32 value, bytes calldata leafPrefix, InnerOp[] calldata path) public pure returns (bytes32 h) {
        _checkLeafPrefix(leafPrefix);
        h = sha256(abi.encodePacked(leafPrefix, _uvarint(key.length), key, uint8(32), sha256(abi.encodePacked(value))));
        for (uint256 i = 0; i < path.length; i++) {
            _checkInner(path[i].prefix, path[i].suffix, i + 1);
            h = sha256(abi.encodePacked(path[i].prefix, h, path[i].suffix));
        }
    }

    /// zz(height 0) zz(size 1) zz(version >= 0), nothing else.
    function _checkLeafPrefix(bytes calldata lp) private pure {
        (uint256 hgt, uint256 p) = _varint(lp, 0);
        uint256 size;
        (size, p) = _varint(lp, p);
        uint256 ver;
        (ver, p) = _varint(lp, p);
        if (hgt != 0 || size != 2 || ver & 1 == 1 || p != lp.length) revert BadStateProof(3);
    }

    /// zz(height >= level) zz(size) zz(version), then 0x20 (left child; suffix 0x20 || right) or
    /// 0x20 || left || 0x20 (right child; no suffix).
    function _checkInner(bytes calldata pre, bytes calldata suf, uint256 level) private pure {
        (uint256 hgt, uint256 p) = _varint(pre, 0);
        uint256 x;
        (x, p) = _varint(pre, p); // size
        if (hgt & 1 == 1 || hgt / 2 < level || x & 1 == 1 || pre[0] == 0x00) revert BadStateProof(3);
        (x, p) = _varint(pre, p); // version
        if (x & 1 == 1) revert BadStateProof(3);
        uint256 rest = pre.length - p;
        bool left = rest == 1 && pre[p] == 0x20 && suf.length == 33 && suf[0] == 0x20;
        bool right = rest == 34 && pre[p] == 0x20 && pre[p + 33] == 0x20 && suf.length == 0;
        if (!left && !right) revert BadStateProof(3);
    }

    /// ICS23 TendermintSpec ops (Cosmos SDK multistore): the app hash for (store name, store root).
    function storeRoot(bytes memory name, bytes32 root, InnerOp[] calldata path) public pure returns (bytes32 h) {
        h = sha256(abi.encodePacked(uint8(0), _uvarint(name.length), name, uint8(32), sha256(abi.encodePacked(root))));
        for (uint256 i = 0; i < path.length; i++) {
            bytes calldata pre = path[i].prefix;
            bytes calldata suf = path[i].suffix;
            bool ok = pre.length > 0 && pre[0] == 0x01 && ((pre.length == 1 && suf.length == 32) || (pre.length == 33 && suf.length == 0));
            if (!ok) revert BadStateProof(2);
            h = sha256(abi.encodePacked(pre, h, suf));
        }
    }

    function _varint(bytes calldata b, uint256 p) private pure returns (uint256 v, uint256 q) {
        uint256 shift;
        for (q = p; q < b.length && q < p + 10; q++) {
            uint8 x = uint8(b[q]);
            v |= uint256(x & 0x7f) << shift;
            shift += 7;
            if (x & 0x80 == 0) return (v, q + 1);
        }
        revert BadStateProof(3);
    }

    function _uvarint(uint256 n) private pure returns (bytes memory out) {
        if (n < 0x80) return abi.encodePacked(uint8(n));
        return abi.encodePacked(uint8(n & 0x7f) | 0x80, uint8(n >> 7)); // keys and names < 16384 bytes
    }

    // ------------------------------------------------------------------ circuit breaker

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function _guard() private view {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
    }

    function pause() external {
        _guard();
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyGov {
        paused = false;
        emit Unpaused();
    }

    /// Guardians or governance: lower the daily limit at once (and drop a pending raise).
    function lowerLimit(uint256 v) external {
        _guard();
        require(v < dailyLimit, "not lower");
        dailyLimit = v;
        pendingAt = 0;
        emit LimitSet(v);
    }

    /// Governance: propose a raise (at most x2 of the current limit), applied LIMIT_DELAY later by anyone.
    function proposeLimit(uint256 v) external onlyGov {
        require(v > dailyLimit && v <= 2 * dailyLimit + 1, "step");
        pendingLimit = v;
        pendingAt = uint64(block.timestamp) + LIMIT_DELAY;
        emit LimitProposed(v, pendingAt);
    }

    function applyLimit() external {
        if (pendingAt == 0 || block.timestamp < pendingAt) revert TooEarly();
        dailyLimit = pendingLimit;
        pendingAt = 0;
        emit LimitSet(dailyLimit);
    }

    function setGuardian(address who, bool on) external onlyGov {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    function setGovernance(address g) external onlyGov {
        governance = g;
    }
}

contracts/ZetaphyCheques.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IChequeERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

/// @title ZetaphyCheques: offline payments with signed cheques (testnet, not audited)
/// @notice One-way payment channels. A payer locks a deposit (native ZETAPHY or an ERC-20) for one
///         payee and names a `signer`: a dedicated key (the hub keeps it encrypted in the browser),
///         not the payer's main wallet. Offline, the signer signs cheques: EIP-712
///         Cheque{channelId, cumulativeAmount}, the TOTAL promised to the payee so far. Each new
///         cheque replaces the last one (a higher total); the payee keeps only the best.
///
///         cash(channelId, cumulative, sig): anyone may submit a cheque; the payee always gets the
///         money: the part of `cumulative` not cashed yet, never more than the deposit (a cheque
///         above the deposit pays what is there; a later topUp lets the same cheque pay the rest).
///
///         Closing: once the channel has expired the payer calls startClose; the payee still has
///         CHALLENGE_PERIOD (24 h) to cash its best cheque; then the payer withdraws the remainder.
///         The payee may end that wait early with release() (after cashing).
///
///         What the payee can rely on offline: a valid cheque for a total up to the deposit it last
///         saw on chain, while the channel is not closing, is money it can cash (the deposit never
///         goes down before the close; nobody else can take it). The payee must cash before
///         expiry + 24 h at the latest (the earliest a close can end).
///
///         No owner, no fee, no upgrade. Tokens: plain ERC-20s; fee-on-transfer tokens are refused
///         (the received amount is measured). Every state change happens before the transfer
///         (checks-effects-interactions) and every entry point is nonReentrant.
contract ZetaphyCheques {
    struct Channel {
        address payer;
        uint64 expiry;   // the payer may start closing from here
        uint64 closeAt;  // 0 = open; else the end of the challenge period (cashing stops, withdraw starts)
        address payee;
        address token;   // address(0) = native ZETAPHY
        address signer;  // the key whose cheques count
        uint256 deposit; // everything deposited
        uint256 paid;    // everything cashed by the payee
        bool done;       // the payer took the remainder: the channel is over
    }

    uint256 public constant CHALLENGE_PERIOD = 24 hours;
    uint256 public constant MAX_DURATION = 366 days;
    bytes32 public constant CHEQUE_TYPEHASH = keccak256("Cheque(uint256 channelId,uint256 cumulativeAmount)");
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    uint256 private constant HALF_N = 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    uint256 public channelCount;
    mapping(uint256 => Channel) public channels;
    uint256 private locked = 1;

    event ChannelOpened(uint256 indexed id, address indexed payer, address indexed payee, address token, uint256 amount, uint64 expiry, address signer);
    event ToppedUp(uint256 indexed id, uint256 amount, uint256 deposit);
    event Extended(uint256 indexed id, uint64 expiry);
    event Cashed(uint256 indexed id, address indexed payee, uint256 cumulative, uint256 amount, address submitter);
    event CloseStarted(uint256 indexed id, uint64 closeAt);
    event Released(uint256 indexed id);
    event Withdrawn(uint256 indexed id, address indexed payer, uint256 amount);

    error BadChannel();
    error NotPayer();
    error NotPayee();
    error BadAmount();
    error BadExpiry();
    error BadValue();
    error Closing();
    error NotClosing();
    error NotExpired();
    error ChallengeOpen();
    error ChannelDone();
    error BadSignature();
    error NothingToCash();
    error FeeOnTransfer();
    error TokenFailed();
    error SendFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    // ------------------------------------------------------------------ EIP-712

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY Cheques"), keccak256("1"), block.chainid, address(this)));
    }

    /// The digest the signer signs for a cheque (eth_signTypedData_v4 gives the same).
    function chequeDigest(uint256 id, uint256 cumulative) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), keccak256(abi.encode(CHEQUE_TYPEHASH, id, cumulative))));
    }

    // ------------------------------------------------------------------ payer

    /// Opens a channel to `payee` with `amount` of `token` (0 = native: send it as msg.value), cheques
    /// signed by `signer`, closable from `expiry`. Returns the channel id (1, 2, ...).
    function open(address payee, address token, uint256 amount, uint64 expiry, address signer)
        external payable nonReentrant returns (uint256 id)
    {
        if (payee == address(0) || signer == address(0) || payee == msg.sender) revert BadChannel();
        if (amount == 0) revert BadAmount();
        if (expiry <= block.timestamp || expiry > block.timestamp + MAX_DURATION) revert BadExpiry();
        id = ++channelCount;
        channels[id] = Channel({ payer: msg.sender, expiry: expiry, closeAt: 0, payee: payee, token: token, signer: signer,
            deposit: amount, paid: 0, done: false });
        emit ChannelOpened(id, msg.sender, payee, token, amount, expiry, signer);
        _pullIn(token, amount);
    }

    /// Adds to the deposit (payer only, not once closing).
    function topUp(uint256 id, uint256 amount) external payable nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (amount == 0) revert BadAmount();
        c.deposit += amount;
        emit ToppedUp(id, amount, c.deposit);
        _pullIn(c.token, amount);
    }

    /// Moves the expiry later (payer only, not once closing).
    function extend(uint256 id, uint64 expiry) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (expiry <= c.expiry || expiry > block.timestamp + MAX_DURATION) revert BadExpiry();
        c.expiry = expiry;
        emit Extended(id, expiry);
    }

    /// After the expiry: starts the challenge period, during which the payee can still cash.
    function startClose(uint256 id) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (block.timestamp < c.expiry) revert NotExpired();
        uint64 at = uint64(block.timestamp + CHALLENGE_PERIOD);
        c.closeAt = at;
        emit CloseStarted(id, at);
    }

    /// After the challenge period (or a release): the payer takes what was not cashed.
    function withdraw(uint256 id) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt == 0) revert NotClosing();
        if (block.timestamp < c.closeAt) revert ChallengeOpen();
        c.done = true;
        uint256 rest = c.deposit - c.paid;
        emit Withdrawn(id, c.payer, rest);
        if (rest != 0) _pay(c.token, c.payer, rest);
    }

    // ------------------------------------------------------------------ payee (and anyone)

    /// Cashes a cheque: pays the payee min(cumulative, deposit) minus what it was already paid.
    /// Anyone may submit it; the money always goes to the payee. Works until the challenge period ends.
    function cash(uint256 id, uint256 cumulative, bytes calldata sig) external nonReentrant returns (uint256 amount) {
        Channel storage c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (c.done) revert ChannelDone();
        if (c.closeAt != 0 && block.timestamp >= c.closeAt) revert ChannelDone();
        if (_recover(chequeDigest(id, cumulative), sig) != c.signer) revert BadSignature();
        uint256 upTo = cumulative < c.deposit ? cumulative : c.deposit;
        if (upTo <= c.paid) revert NothingToCash();
        amount = upTo - c.paid;
        c.paid = upTo;
        emit Cashed(id, c.payee, cumulative, amount, msg.sender);
        _pay(c.token, c.payee, amount);
    }

    /// The payee gives up the rest of the channel (after cashing): the payer may withdraw at once.
    function release(uint256 id) external nonReentrant {
        Channel storage c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (msg.sender != c.payee) revert NotPayee();
        if (c.done) revert ChannelDone();
        c.closeAt = uint64(block.timestamp);
        emit Released(id);
    }

    /// What cash(id, cumulative, …) would pay now with a valid cheque (0 if nothing / closed).
    function cashable(uint256 id, uint256 cumulative) external view returns (uint256) {
        Channel storage c = channels[id];
        if (c.payer == address(0) || c.done || (c.closeAt != 0 && block.timestamp >= c.closeAt)) return 0;
        uint256 upTo = cumulative < c.deposit ? cumulative : c.deposit;
        return upTo > c.paid ? upTo - c.paid : 0;
    }

    // ------------------------------------------------------------------ internals

    function _payerChannel(uint256 id) private view returns (Channel storage c) {
        c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (msg.sender != c.payer) revert NotPayer();
        if (c.done) revert ChannelDone();
    }

    /// Takes `amount` from the caller: msg.value for native, else transferFrom with the received
    /// amount measured (a token that delivers less, e.g. fee on transfer, is refused).
    function _pullIn(address token, uint256 amount) private {
        if (token == address(0)) {
            if (msg.value != amount) revert BadValue();
            return;
        }
        if (msg.value != 0) revert BadValue();
        if (token.code.length == 0) revert TokenFailed();
        uint256 before = IChequeERC20(token).balanceOf(address(this));
        _safe(token, abi.encodeCall(IChequeERC20.transferFrom, (msg.sender, address(this), amount)));
        if (IChequeERC20(token).balanceOf(address(this)) - before != amount) revert FeeOnTransfer();
    }

    function _pay(address token, address to, uint256 amount) private {
        if (token == address(0)) {
            (bool ok, ) = to.call{value: amount}("");
            if (!ok) revert SendFailed();
        } else {
            _safe(token, abi.encodeCall(IChequeERC20.transfer, (to, amount)));
        }
    }

    /// ecrecover of a 65-byte r‖s‖v signature; refuses high s (malleability) and v other than 27/28 (or 0/1).
    function _recover(bytes32 digest, bytes calldata sig) private pure returns (address got) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27;
        if ((v != 27 && v != 28) || uint256(s) > HALF_N) revert BadSignature();
        got = ecrecover(digest, v, r, s);
        if (got == address(0)) revert BadSignature();
    }

    /// ERC-20 call that accepts tokens returning nothing (USDT style) but not false, a revert or no code.
    function _safe(address token, bytes memory data) private {
        if (token.code.length == 0) revert TokenFailed();
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length != 32 || !abi.decode(ret, (bool))))) revert TokenFailed();
    }
}

contracts/ZetaphyEarly.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Early (ZEARLY): the community token of the ZETAPHY testnet airdrop
/// @notice A plain ERC-20 with a fixed supply of 1,000,000,000, all created once for the holder given at
///         deploy (the airdrop wallet). No owner, no mint, no pause, no fee: nobody can create more or stop
///         transfers. It shows who joined early; it is NOT ZETAPHY, it is not converted into ZETAPHY, and
///         it has no value (zetaphy-chain/rewards/EARLY.md).
///         batchTransfer sends the same amount from the caller to many wallets in one transaction (the airdrop).
contract ZetaphyEarly {
    string public constant name = "ZETAPHY Early";
    string public constant symbol = "ZEARLY";
    uint8 public constant decimals = 18;
    uint256 public constant totalSupply = 1_000_000_000 ether;
    uint256 public constant MAX_BATCH = 500;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    error ZeroAddress();
    error InsufficientBalance();
    error InsufficientAllowance();
    error BadBatch();

    constructor(address holder) {
        if (holder == address(0)) revert ZeroAddress();
        balanceOf[holder] = totalSupply;
        emit Transfer(address(0), holder, totalSupply);
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _move(msg.sender, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        if (spender == address(0)) revert ZeroAddress();
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            if (a < value) revert InsufficientAllowance();
            unchecked { allowance[from][msg.sender] = a - value; }
        }
        _move(from, to, value);
        return true;
    }

    /// @notice Sends `each` from the caller to every address in `to` (1 to MAX_BATCH addresses).
    function batchTransfer(address[] calldata to, uint256 each) external returns (bool) {
        uint256 n = to.length;
        if (n == 0 || n > MAX_BATCH) revert BadBatch();
        uint256 total = each * n;
        uint256 b = balanceOf[msg.sender];
        if (b < total) revert InsufficientBalance();
        unchecked { balanceOf[msg.sender] = b - total; }
        for (uint256 i; i < n; ++i) {
            address t = to[i];
            if (t == address(0)) revert ZeroAddress();
            unchecked { balanceOf[t] += each; } // sum of all balances is totalSupply: no overflow
            emit Transfer(msg.sender, t, each);
        }
        return true;
    }

    function _move(address from, address to, uint256 value) private {
        if (to == address(0)) revert ZeroAddress();
        uint256 b = balanceOf[from];
        if (b < value) revert InsufficientBalance();
        unchecked {
            balanceOf[from] = b - value;
            balanceOf[to] += value;
        }
        emit Transfer(from, to, value);
    }
}

contracts/ZetaphyEarlyFarm.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC20F {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

/// @title ZETAPHY Early farm: stake ZEARLY/ZETAPHY pool shares (LP), earn ZEARLY over time
/// @notice The classic StakingRewards design: the operator funds a reward period (ZEARLY sent here first, then
///         `notifyReward`), rewards stream per second to stakers by their share of the stake. Stakers can withdraw
///         their LP and claim at any time; nobody else can touch the staked LP. The operator can only take back
///         ZEARLY that no reward period promised; what streams while nothing is staked is owed to nobody and
///         stops being promised at the next update, so the operator can recover it (EF-1). Testnet; no value
///         (zetaphy-chain/rewards/EARLY.md).
contract ZetaphyEarlyFarm {
    IERC20F public immutable stakingToken; // the ZEARLY/ZETAPHY pair (LP)
    IERC20F public immutable rewardsToken; // ZEARLY
    address public operator;

    uint256 public periodFinish;
    uint256 public rewardRate;          // ZEARLY per second
    uint256 public lastUpdate;
    uint256 public rewardPerTokenStored;
    uint256 public owed;                // rewards promised and not yet claimed (funded, never withdrawable)

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => uint256) public userPaid;
    mapping(address => uint256) public rewards;

    uint256 private locked = 1;

    event Staked(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event RewardPaid(address indexed user, uint256 reward);
    event RewardAdded(uint256 reward, uint256 duration);
    event OperatorSet(address operator);

    error NotOperator();
    error ZeroAddress();
    error ZeroAmount();
    error Underfunded();
    error PeriodActive();
    error Reentrancy();
    error TransferFailed();

    modifier onlyOperator() { if (msg.sender != operator) revert NotOperator(); _; }
    modifier nonReentrant() { if (locked != 1) revert Reentrancy(); locked = 2; _; locked = 1; }
    modifier update(address a) {
        uint256 t = lastTime();
        if (totalSupply == 0 && t > lastUpdate) {
            // nobody staked: what streamed since lastUpdate is owed to nobody; it is no longer promised, so
            // recover() can take it back (EF-1)
            owed -= (t - lastUpdate) * rewardRate;
        } else {
            rewardPerTokenStored = rewardPerToken();
        }
        lastUpdate = t;
        if (a != address(0)) { rewards[a] = earned(a); userPaid[a] = rewardPerTokenStored; }
        _;
    }

    constructor(address lp, address zearly, address operator_) {
        if (lp == address(0) || zearly == address(0) || operator_ == address(0)) revert ZeroAddress();
        if (lp == zearly) revert ZeroAddress(); // staked LP and rewards are kept apart
        stakingToken = IERC20F(lp);
        rewardsToken = IERC20F(zearly);
        operator = operator_;
        emit OperatorSet(operator_);
    }

    function lastTime() public view returns (uint256) { return block.timestamp < periodFinish ? block.timestamp : periodFinish; }

    function rewardPerToken() public view returns (uint256) {
        if (totalSupply == 0) return rewardPerTokenStored;
        return rewardPerTokenStored + (lastTime() - lastUpdate) * rewardRate * 1e18 / totalSupply;
    }

    function earned(address a) public view returns (uint256) {
        return balanceOf[a] * (rewardPerToken() - userPaid[a]) / 1e18 + rewards[a];
    }

    function stake(uint256 amount) external nonReentrant update(msg.sender) {
        if (amount == 0) revert ZeroAmount();
        totalSupply += amount;
        balanceOf[msg.sender] += amount;
        if (!stakingToken.transferFrom(msg.sender, address(this), amount)) revert TransferFailed();
        emit Staked(msg.sender, amount);
    }

    function withdraw(uint256 amount) public nonReentrant update(msg.sender) {
        if (amount == 0) revert ZeroAmount();
        totalSupply -= amount;
        balanceOf[msg.sender] -= amount;
        if (!stakingToken.transfer(msg.sender, amount)) revert TransferFailed();
        emit Withdrawn(msg.sender, amount);
    }

    function getReward() public nonReentrant update(msg.sender) {
        uint256 r = rewards[msg.sender];
        if (r == 0) return;
        rewards[msg.sender] = 0;
        owed -= r;
        if (!rewardsToken.transfer(msg.sender, r)) revert TransferFailed();
        emit RewardPaid(msg.sender, r);
    }

    function exit() external {
        uint256 b = balanceOf[msg.sender];
        if (b != 0) withdraw(b);
        getReward();
    }

    /// @notice Starts (or extends) a reward period: `reward` ZEARLY over `duration` seconds. The ZEARLY must be here
    ///         already, on top of what earlier periods still owe.
    function notifyReward(uint256 reward, uint256 duration) external onlyOperator update(address(0)) {
        if (duration == 0) revert ZeroAmount();
        uint256 left = block.timestamp < periodFinish ? (periodFinish - block.timestamp) * rewardRate : 0;
        uint256 total = reward + left;
        // what earlier periods already streamed and nobody claimed yet is `owed` minus `left`
        uint256 streamed = owed - left;
        if (rewardsToken.balanceOf(address(this)) < streamed + total) revert Underfunded();
        rewardRate = total / duration;
        owed = streamed + rewardRate * duration;
        lastUpdate = block.timestamp;
        periodFinish = block.timestamp + duration;
        emit RewardAdded(reward, duration);
    }

    /// @notice Takes back ZEARLY no reward period promised (never the staked LP, never what stakers are owed).
    function recover(address to, uint256 amount) external onlyOperator {
        if (to == address(0)) revert ZeroAddress();
        if (rewardsToken.balanceOf(address(this)) < owed + amount) revert Underfunded();
        if (!rewardsToken.transfer(to, amount)) revert TransferFailed();
    }

    function setOperator(address o) external onlyOperator {
        if (o == address(0)) revert ZeroAddress();
        operator = o;
        emit OperatorSet(o);
    }
}

contracts/ZetaphyEarlyPass.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZearly {
    function balanceOf(address) external view returns (uint256);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

/// @title ZETAPHY Early Pass: an NFT paid for in ZETAPHY Early (ZEARLY)
/// @notice Anyone may mint one pass per wallet by paying `price` ZEARLY, which is burned (sent to 0x…dEaD).
///         Before `earlyUntil`, only wallets holding at least `minHold` ZEARLY may mint: the early supporters' perk.
///         At most `maxSupply` passes. The picture and the metadata are drawn on chain (no server, no IPFS).
///         No owner, no admin: the rules above are fixed at deploy. Testnet; no value (zetaphy-chain/rewards/EARLY.md).
contract ZetaphyEarlyPass {
    string public constant name = "ZETAPHY Early Pass";
    string public constant symbol = "ZEPASS";
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;

    IZearly public immutable zearly;
    uint256 public immutable price;
    uint256 public immutable maxSupply;
    uint64 public immutable earlyUntil;
    uint256 public immutable minHold;

    uint256 public totalSupply;
    mapping(uint256 => address) private _owner;
    mapping(address => uint256) public balanceOf;
    mapping(uint256 => address) public getApproved;
    mapping(address => mapping(address => bool)) public isApprovedForAll;
    mapping(address => bool) public minted; // one pass per wallet, ever

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);

    error SoldOut();
    error AlreadyMinted();
    error EarlyHoldersOnly();
    error PaymentFailed();
    error NotToken();
    error NotAllowed();
    error ZeroAddress();
    error NotReceiver();

    constructor(address zearly_, uint256 price_, uint256 maxSupply_, uint64 earlyUntil_, uint256 minHold_) {
        if (zearly_ == address(0)) revert ZeroAddress();
        zearly = IZearly(zearly_);
        price = price_;
        maxSupply = maxSupply_;
        earlyUntil = earlyUntil_;
        minHold = minHold_;
    }

    /// @notice Mint your pass: pay `price` ZEARLY (approve this contract first); it is burned.
    function mint() external returns (uint256 id) {
        if (totalSupply >= maxSupply) revert SoldOut();
        if (minted[msg.sender]) revert AlreadyMinted();
        if (block.timestamp < earlyUntil && zearly.balanceOf(msg.sender) < minHold) revert EarlyHoldersOnly();
        minted[msg.sender] = true;
        id = ++totalSupply;
        if (price != 0 && !zearly.transferFrom(msg.sender, BURN, price)) revert PaymentFailed();
        _owner[id] = msg.sender;
        balanceOf[msg.sender] += 1;
        emit Transfer(address(0), msg.sender, id);
    }

    // ------------------------------------------------------------------ ERC-721
    function ownerOf(uint256 id) public view returns (address o) {
        o = _owner[id];
        if (o == address(0)) revert NotToken();
    }

    function approve(address to, uint256 id) external {
        address o = ownerOf(id);
        if (msg.sender != o && !isApprovedForAll[o][msg.sender]) revert NotAllowed();
        getApproved[id] = to;
        emit Approval(o, to, id);
    }

    function setApprovalForAll(address operator, bool approved) external {
        isApprovedForAll[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function transferFrom(address from, address to, uint256 id) public {
        if (to == address(0)) revert ZeroAddress();
        address o = ownerOf(id);
        if (o != from) revert NotAllowed();
        if (msg.sender != o && getApproved[id] != msg.sender && !isApprovedForAll[o][msg.sender]) revert NotAllowed();
        delete getApproved[id];
        unchecked { balanceOf[from] -= 1; balanceOf[to] += 1; }
        _owner[id] = to;
        emit Transfer(from, to, id);
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        safeTransferFrom(from, to, id, "");
    }

    function safeTransferFrom(address from, address to, uint256 id, bytes memory data) public {
        transferFrom(from, to, id);
        if (to.code.length != 0 && IERC721Receiver(to).onERC721Received(msg.sender, from, id, data) != IERC721Receiver.onERC721Received.selector) {
            revert NotReceiver();
        }
    }

    function supportsInterface(bytes4 i) external pure returns (bool) {
        return i == 0x01ffc9a7 || i == 0x80ac58cd || i == 0x5b5e139f; // ERC-165, ERC-721, ERC-721 metadata
    }

    // ------------------------------------------------------------------ metadata, drawn on chain
    function tokenURI(uint256 id) external view returns (string memory) {
        ownerOf(id);
        string memory n = _str(id);
        string memory svg = string.concat(
            "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 512 512'>",
            "<defs><radialGradient id='b' cx='.35' cy='.3' r='.85'><stop offset='0' stop-color='#1B2540'/><stop offset='1' stop-color='#070B16'/></radialGradient>",
            "<linearGradient id='g' x1='1' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#FCD772'/><stop offset='1' stop-color='#E0981F'/></linearGradient></defs>",
            "<rect width='512' height='512' rx='48' fill='url(#b)'/>",
            "<path d='M168 140 H344 M168 316 H344' stroke='#fff' stroke-width='56' stroke-linecap='round'/>",
            "<path d='M344 140 L168 316' stroke='url(#g)' stroke-width='56' stroke-linecap='round'/>",
            "<circle cx='392' cy='92' r='26' fill='url(#g)'/>",
            "<text x='256' y='418' fill='#FCD772' font-family='sans-serif' font-size='34' font-weight='700' text-anchor='middle' letter-spacing='4'>EARLY PASS</text>",
            "<text x='256' y='464' fill='#fff' font-family='monospace' font-size='28' text-anchor='middle'>#", n, "</text></svg>"
        );
        string memory json = string.concat(
            '{"name":"ZETAPHY Early Pass #', n,
            '","description":"Minted with ZETAPHY Early (ZEARLY) on the ZETAPHY testnet. One per wallet. No value.",',
            '"image":"data:image/svg+xml;base64,', _b64(bytes(svg)),
            '","attributes":[{"trait_type":"Number","value":', n, '}]}'
        );
        return string.concat("data:application/json;base64,", _b64(bytes(json)));
    }

    function _str(uint256 v) private pure returns (string memory) {
        if (v == 0) return "0";
        uint256 len;
        for (uint256 t = v; t != 0; t /= 10) len++;
        bytes memory b = new bytes(len);
        for (; v != 0; v /= 10) b[--len] = bytes1(uint8(48 + v % 10));
        return string(b);
    }

    function _b64(bytes memory data) private pure returns (string memory) {
        bytes memory T = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        uint256 n = data.length;
        if (n == 0) return "";
        bytes memory out = new bytes(4 * ((n + 2) / 3));
        uint256 j;
        for (uint256 i; i < n; i += 3) {
            uint256 a = uint8(data[i]);
            uint256 b = i + 1 < n ? uint8(data[i + 1]) : 0;
            uint256 c = i + 2 < n ? uint8(data[i + 2]) : 0;
            uint256 x = (a << 16) | (b << 8) | c;
            out[j++] = T[(x >> 18) & 63];
            out[j++] = T[(x >> 12) & 63];
            out[j++] = i + 1 < n ? T[(x >> 6) & 63] : bytes1("=");
            out[j++] = i + 2 < n ? T[x & 63] : bytes1("=");
        }
        return string(out);
    }
}

contracts/ZetaphyEarlyPolls.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC20P {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

/// @title ZETAPHY Early polls: community opinion polls weighted by ZEARLY
/// @notice Anyone may open a poll by locking `deposit` ZEARLY (given back when it ends). A vote locks ZEARLY on one
///         option until the poll ends; the weight is the ZEARLY locked, so the same coins cannot vote twice. After
///         the end everyone takes their ZEARLY back. Polls are opinions only: nothing on the chain follows them
///         (the chain's own votes are x/gov). Text is shown as text by the hub. Testnet; no value.
contract ZetaphyEarlyPolls {
    uint256 public constant MAX_OPTIONS = 8;
    uint256 public constant MAX_TEXT = 280;
    uint256 public constant MAX_OPTION_TEXT = 64;
    uint64 public constant MIN_DURATION = 1 hours;
    uint64 public constant MAX_DURATION = 30 days;

    IERC20P public immutable token;
    uint256 public immutable deposit;

    struct Poll { address creator; uint64 end; bool depositBack; string question; string[] options; uint256[] tally; }
    Poll[] private polls;
    mapping(uint256 => mapping(address => uint256)) public locked;  // poll => voter => ZEARLY locked
    mapping(uint256 => mapping(address => uint8)) public choiceOf;  // option index + 1 (0 = has not voted)

    event PollCreated(uint256 indexed id, address indexed creator, uint64 end);
    event Voted(uint256 indexed id, address indexed voter, uint8 option, uint256 amount);
    event Released(uint256 indexed id, address indexed who, uint256 amount);

    error BadPoll();
    error Ended();
    error NotEnded();
    error OtherOption();
    error ZeroAmount();
    error NothingLocked();
    error TransferFailed();

    constructor(address token_, uint256 deposit_) {
        if (token_ == address(0)) revert BadPoll();
        token = IERC20P(token_);
        deposit = deposit_;
    }

    function create(string calldata question, string[] calldata options, uint64 duration) external returns (uint256 id) {
        if (bytes(question).length == 0 || bytes(question).length > MAX_TEXT) revert BadPoll();
        if (options.length < 2 || options.length > MAX_OPTIONS) revert BadPoll();
        if (duration < MIN_DURATION || duration > MAX_DURATION) revert BadPoll();
        for (uint256 i; i < options.length; ++i) {
            if (bytes(options[i]).length == 0 || bytes(options[i]).length > MAX_OPTION_TEXT) revert BadPoll();
        }
        if (deposit != 0 && !token.transferFrom(msg.sender, address(this), deposit)) revert TransferFailed();
        id = polls.length;
        Poll storage p = polls.push();
        p.creator = msg.sender;
        p.end = uint64(block.timestamp) + duration;
        p.question = question;
        for (uint256 i; i < options.length; ++i) { p.options.push(options[i]); p.tally.push(0); }
        emit PollCreated(id, msg.sender, p.end);
    }

    /// @notice Locks `amount` ZEARLY on `option` until the poll ends (more can be added to the same option).
    function vote(uint256 id, uint8 option, uint256 amount) external {
        if (id >= polls.length) revert BadPoll();
        Poll storage p = polls[id];
        if (block.timestamp >= p.end) revert Ended();
        if (option >= p.options.length) revert BadPoll();
        if (amount == 0) revert ZeroAmount();
        uint8 c = choiceOf[id][msg.sender];
        if (c != 0 && c != option + 1) revert OtherOption();
        choiceOf[id][msg.sender] = option + 1;
        locked[id][msg.sender] += amount;
        p.tally[option] += amount;
        if (!token.transferFrom(msg.sender, address(this), amount)) revert TransferFailed();
        emit Voted(id, msg.sender, option, amount);
    }

    /// @notice After the end: the voter's locked ZEARLY back, and the creator's deposit.
    function release(uint256 id) external {
        if (id >= polls.length) revert BadPoll();
        Poll storage p = polls[id];
        if (block.timestamp < p.end) revert NotEnded();
        uint256 amount = locked[id][msg.sender];
        locked[id][msg.sender] = 0;
        if (msg.sender == p.creator && !p.depositBack) { p.depositBack = true; amount += deposit; }
        if (amount == 0) revert NothingLocked();
        if (!token.transfer(msg.sender, amount)) revert TransferFailed();
        emit Released(id, msg.sender, amount);
    }

    function count() external view returns (uint256) { return polls.length; }

    function poll(uint256 id) external view returns (address creator, uint64 end, string memory question, string[] memory options, uint256[] memory tally) {
        if (id >= polls.length) revert BadPoll();
        Poll storage p = polls[id];
        return (p.creator, p.end, p.question, p.options, p.tally);
    }
}

contracts/ZetaphyOfflineCash.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZetaphyOfflineCash: bonded bearer notes passed hand to hand with no internet (testnet, not audited)
/// @notice Design and threat model: docs/future/offline-cash.md.
///
///  Notes. An issuer locks native ZETAPHY as notes (any denominations, `issue`) until `lockUntil`: before
///  then nobody but a holder can take a note's value out (the issuer cannot reclaim early). The issuer also
///  keeps an issuer bond of at least 150% of its outstanding notes, locked until every note's claim window
///  is over (bondIssuer); it pays the victims of the issuer's own double-spends.
///
///  Holding and passing on. Every holder is an ML-DSA-44 key (keccak256 of the 1312-byte public key). The
///  first holder is the issuer's key; a holder passes the note on by signing a Link (noteId, seq, prev, to,
///  cond) with its key, offline: `prev` is the hash of the previous link (or the note's root), `to` the next
///  holder's key. The note travels as its chain of links; the payee checks it with no network.
///
///  Cashing. Any holder signs a Terminal (prev, payout, fee): "pay this note to `payout`, `fee` to whoever
///  submits it". redeem(noteId, links, terminal) can be sent by anyone (a relayer earns the fee):
///   - the note is still live: the earliest valid chain to reach the chain wins; the note's value is paid;
///   - the note was already paid through another chain: the two chains split at some link: its holder
///     signed two different spends of the same `prev` (a double-spend). This chain's holder is the victim
///     and is paid the note's value from the cheater's bond: the ISSUER bond when the issuer double-spent
///     (split at seq 0), else the HOLDER bond of the key that split it (bondHolder). The victim bears what
///     the bond cannot cover (no bond, or bond already spent on other victims): payees check the bonds
///     of every key in the chain (the hub shows the covered amount). Claims are accepted until
///     lockUntil + CLAIM_WINDOW.
///  Every message spent is recorded (spentBy[prev] = the spending message), so a second claim, a replay,
///  or an old chain is refused, and further splits down a paid victim branch are still traced to whoever
///  split them.
///
///  Atomic swap ticket. Two holders swap two notes offline: a ticket fixes both legs (note, seq, prev, to,
///  payout) and a deadline; each holder signs its leg as a Link whose `cond` is the ticket id. A conditional
///  link only counts through settleSwap, which pays BOTH notes (A to its new holder's payout, B to its) in
///  one transaction, or neither. Until it is settled a ticket is only an offer: its legs are not spends.
///
///  ML-DSA-44 checks use ZETAPHY's precompile at 0x…0900 (FIPS 204, pure, empty context) over 32-byte
///  digests. Native coin only. No owner, no fee, no upgrade. Checks-effects-interactions, nonReentrant.
contract ZetaphyOfflineCash {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint8 public constant VARIANT = 44;
    uint256 public constant PK_BYTES = 1312;
    uint256 public constant BOND_BPS = 15_000;            // issuer bond >= 150% of outstanding notes
    uint256 public constant CLAIM_WINDOW = 30 days;       // fraud claims until lockUntil + CLAIM_WINDOW
    uint256 public constant MIN_LOCK = 1 days;
    uint256 public constant MAX_LOCK = 366 days;
    uint256 public constant MAX_NOTES_PER_ISSUE = 64;
    uint256 public constant MAX_LINKS = 64;

    bytes32 public constant NOTE_TAG = keccak256("ZetaphyCash.Note(uint256 id,uint256 value,uint256 lockUntil,bytes32 issuerKey)");
    bytes32 public constant LINK_TAG = keccak256("ZetaphyCash.Link(uint256 noteId,uint256 seq,bytes32 prev,bytes32 to,bytes32 cond)");
    bytes32 public constant TERMINAL_TAG = keccak256("ZetaphyCash.Terminal(bytes32 prev,address payout,uint256 fee)");
    bytes32 public constant SWAP_TAG = keccak256(
        "ZetaphyCash.Swap(uint256 noteA,uint256 seqA,bytes32 prevA,bytes32 toA,address payoutA,uint256 noteB,uint256 seqB,bytes32 prevB,bytes32 toB,address payoutB,uint256 deadline)"
    );
    bytes32 public constant SWAP_DONE_TAG = keccak256("ZetaphyCash.SwapDone(bytes32 ticket,uint256 leg)");
    bytes32 public immutable DOMAIN;

    struct Note {
        address issuer;
        uint96 value;
        uint64 lockUntil;
        bool done;          // paid out (redeemed, swapped) or reclaimed by the issuer
        bytes32 issuerKey;  // holder 0
    }
    struct Bond {
        address owner;
        uint64 until;       // no withdrawal before this
        uint256 amount;
    }
    struct Link {
        bytes32 to;
        bytes32 cond;       // 0, or the swap ticket id this leg belongs to
        bytes pk;           // the signer's ML-DSA-44 public key (the current holder)
        bytes sig;
    }
    struct Terminal {
        address payout;
        uint96 fee;         // to msg.sender (a relayer), out of what is paid
        bytes pk;
        bytes sig;
    }
    struct Ticket {
        uint256 noteA; uint256 seqA; bytes32 prevA; bytes32 toA; address payoutA;
        uint256 noteB; uint256 seqB; bytes32 prevB; bytes32 toB; address payoutB;
        uint256 deadline;
    }

    uint256 public noteCount;
    mapping(uint256 => Note) public notes;
    mapping(address => Bond) public issuerBonds;
    mapping(bytes32 => Bond) public holderBonds;
    mapping(address => uint256) public outstanding;     // issuer => value of its notes not done
    mapping(bytes32 => bytes32) public spentBy;         // prev => the paid message that spent it
    mapping(bytes32 => bool) public forkPaid;           // a victim's first diverging message, once compensated
    mapping(bytes32 => bool) public swapSettled;
    uint256 private locked = 1;

    event IssuerBonded(address indexed issuer, uint256 amount, uint64 until, uint256 outstanding);
    event HolderBonded(bytes32 indexed key, address indexed owner, uint256 amount, uint64 until);
    event BondWithdrawn(address indexed owner, bytes32 indexed key, uint256 amount);
    event NoteIssued(uint256 indexed id, address indexed issuer, bytes32 issuerKey, uint96 value, uint64 lockUntil);
    event Redeemed(uint256 indexed id, address indexed payout, uint256 amount, uint256 fee, uint256 links, address submitter);
    event FraudPaid(uint256 indexed id, bytes32 indexed cheater, address indexed victim, uint256 seq, uint256 paid, uint256 shortfall, bool issuerBond);
    event SwapSettled(bytes32 indexed ticket, uint256 noteA, uint256 noteB, address payoutA, address payoutB);
    event Reclaimed(uint256 indexed id, address indexed issuer, uint256 amount);

    error BadValue();
    error BadLock();
    error BadBond();
    error BondTooSmall();
    error BondLocked();
    error NotBondOwner();
    error BadNote();
    error NoteDone();
    error TooManyLinks();
    error WrongKey();
    error BadSignature();
    error UnsettledSwap();
    error AlreadyPaid();
    error NothingToClaim();
    error OwnDoubleSpend();
    error ClaimWindowOver();
    error BondEmpty();
    error BadFee();
    error BadTicket();
    error Expired();
    error NotIssuer();
    error NotUnlocked();
    error SendFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    constructor() {
        DOMAIN = keccak256(abi.encode(keccak256("ZETAPHY Offline Cash v1"), block.chainid, address(this)));
    }

    // ------------------------------------------------------------------ bonds

    /// Adds to the caller's issuer bond and/or moves its lock later (never earlier).
    function bondIssuer(uint64 until) external payable nonReentrant {
        Bond storage b = issuerBonds[msg.sender];
        if (until < b.until || until > block.timestamp + MAX_LOCK + CLAIM_WINDOW) revert BadLock();
        if (msg.value == 0 && until == b.until) revert BadValue();
        b.owner = msg.sender;
        b.until = until;
        b.amount += msg.value;
        emit IssuerBonded(msg.sender, b.amount, until, outstanding[msg.sender]);
    }

    /// A bond that answers for double-spends signed by holder key `key`. The first bonder owns it;
    /// only the owner adds to it, extends it, and withdraws it (after `until`).
    function bondHolder(bytes32 key, uint64 until) external payable nonReentrant {
        Bond storage b = holderBonds[key];
        if (key == bytes32(0)) revert BadBond();
        if (b.owner != address(0) && b.owner != msg.sender) revert NotBondOwner();
        if (until < b.until || until > block.timestamp + MAX_LOCK + CLAIM_WINDOW) revert BadLock();
        if (msg.value == 0 && until == b.until) revert BadValue();
        b.owner = msg.sender;
        b.until = until;
        b.amount += msg.value;
        emit HolderBonded(key, msg.sender, b.amount, until);
    }

    function withdrawIssuerBond() external nonReentrant {
        Bond storage b = issuerBonds[msg.sender];
        if (block.timestamp <= b.until) revert BondLocked();
        uint256 amount = b.amount;
        if (amount == 0) revert BondEmpty();
        b.amount = 0;
        emit BondWithdrawn(msg.sender, bytes32(0), amount);
        _send(msg.sender, amount);
    }

    function withdrawHolderBond(bytes32 key) external nonReentrant {
        Bond storage b = holderBonds[key];
        if (b.owner != msg.sender) revert NotBondOwner();
        if (block.timestamp <= b.until) revert BondLocked();
        uint256 amount = b.amount;
        if (amount == 0) revert BondEmpty();
        b.amount = 0;
        emit BondWithdrawn(msg.sender, key, amount);
        _send(msg.sender, amount);
    }

    // ------------------------------------------------------------------ notes

    /// Locks msg.value as notes of `values` held by the issuer's ML-DSA-44 key `issuerKey` until `lockUntil`.
    /// Needs an issuer bond >= 150% of all outstanding notes, locked until lockUntil + CLAIM_WINDOW at least.
    function issue(bytes32 issuerKey, uint64 lockUntil, uint96[] calldata values) external payable nonReentrant returns (uint256 firstId) {
        uint256 n = values.length;
        if (n == 0 || n > MAX_NOTES_PER_ISSUE || issuerKey == bytes32(0)) revert BadNote();
        if (lockUntil < block.timestamp + MIN_LOCK || lockUntil > block.timestamp + MAX_LOCK) revert BadLock();
        uint256 sum;
        for (uint256 i; i < n; ++i) {
            if (values[i] == 0) revert BadValue();
            sum += values[i];
        }
        if (msg.value != sum) revert BadValue();
        uint256 out = outstanding[msg.sender] + sum;
        Bond storage b = issuerBonds[msg.sender];
        if (b.amount * 10_000 < out * BOND_BPS) revert BondTooSmall();
        if (b.until < uint256(lockUntil) + CLAIM_WINDOW) revert BondLocked();
        outstanding[msg.sender] = out;
        firstId = noteCount + 1;
        for (uint256 i; i < n; ++i) {
            uint256 id = firstId + i;
            notes[id] = Note(msg.sender, values[i], lockUntil, false, issuerKey);
            emit NoteIssued(id, msg.sender, issuerKey, values[i], lockUntil);
        }
        noteCount = firstId + n - 1;
        emit IssuerBonded(msg.sender, b.amount, b.until, out); // the bond as it now stands (for offline proofs)
    }

    /// After lockUntil, the issuer takes back notes nobody cashed.
    function reclaim(uint256[] calldata ids) external nonReentrant {
        uint256 total;
        for (uint256 i; i < ids.length; ++i) {
            Note storage nt = notes[ids[i]];
            if (nt.issuer != msg.sender) revert NotIssuer();
            if (block.timestamp <= nt.lockUntil) revert NotUnlocked();
            if (nt.done) revert NoteDone();
            nt.done = true;
            total += nt.value;
            emit Reclaimed(ids[i], msg.sender, nt.value);
        }
        outstanding[msg.sender] -= total;
        _send(msg.sender, total);
    }

    /// Cashes a note through its chain of links and the last holder's terminal: pays the note if it is live,
    /// else compensates this (victim) chain from the bond of whoever double-spent it.
    function redeem(uint256 id, Link[] calldata links, Terminal calldata t) external nonReentrant {
        Note storage nt = notes[id];
        if (nt.issuer == address(0)) revert BadNote();
        (bytes32[] memory prevs, bytes32[] memory msgs, bytes32[] memory keys) = _walk(id, nt, links, false);
        uint256 n = links.length;
        bytes32 term = terminalHash(prevs[n], t.payout, t.fee);
        _check(keys[n], term, t.pk, t.sig);
        msgs[n] = term;

        if (!nt.done) {
            for (uint256 i; i <= n; ++i) spentBy[prevs[i]] = msgs[i];
            nt.done = true;
            outstanding[nt.issuer] -= nt.value;
            _payout(id, nt.value, t, n);
            return;
        }

        // The note was paid through another chain: find where this one split from the paid history.
        if (block.timestamp > uint256(nt.lockUntil) + CLAIM_WINDOW) revert ClaimWindowOver();
        uint256 f = type(uint256).max;
        for (uint256 i; i <= n; ++i) {
            bytes32 s = spentBy[prevs[i]];
            if (s == msgs[i] || (i < n && forkPaid[msgs[i]])) continue;
            if (s == bytes32(0)) revert NothingToClaim(); // reclaimed by the issuer, or never spent this way
            f = i;
            break;
        }
        if (f == type(uint256).max) revert AlreadyPaid();
        if (f == n) revert OwnDoubleSpend(); // the claimant itself spent the note another way
        forkPaid[msgs[f]] = true;
        for (uint256 i = f + 1; i <= n; ++i) spentBy[prevs[i]] = msgs[i];

        Bond storage b = f == 0 ? issuerBonds[nt.issuer] : holderBonds[keys[f]];
        uint256 pay = b.amount < nt.value ? b.amount : nt.value;
        if (pay == 0) revert BondEmpty();
        b.amount -= pay;
        emit FraudPaid(id, keys[f], t.payout, f, pay, nt.value - pay, f == 0);
        _payout(id, pay, t, n);
    }

    /// Settles a swap ticket: both legs (the last link of each chain, signed by the holders) pay together.
    function settleSwap(Ticket calldata tk, Link[] calldata linksA, Link[] calldata linksB) external nonReentrant {
        if (block.timestamp > tk.deadline) revert Expired();
        if (tk.noteA == tk.noteB || tk.payoutA == address(0) || tk.payoutB == address(0)) revert BadTicket();
        bytes32 tid = ticketId(tk);
        if (swapSettled[tid]) revert AlreadyPaid();
        Note storage na = notes[tk.noteA];
        Note storage nb = notes[tk.noteB];
        if (na.issuer == address(0) || nb.issuer == address(0)) revert BadNote();
        if (na.done || nb.done) revert NoteDone();
        _settleLeg(tk.noteA, na, linksA, tk.seqA, tk.prevA, tk.toA, tid, 0);
        _settleLeg(tk.noteB, nb, linksB, tk.seqB, tk.prevB, tk.toB, tid, 1);
        swapSettled[tid] = true;
        na.done = true;
        nb.done = true;
        outstanding[na.issuer] -= na.value;
        outstanding[nb.issuer] -= nb.value;
        emit SwapSettled(tid, tk.noteA, tk.noteB, tk.payoutA, tk.payoutB);
        emit Redeemed(tk.noteA, tk.payoutA, na.value, 0, linksA.length, msg.sender);
        emit Redeemed(tk.noteB, tk.payoutB, nb.value, 0, linksB.length, msg.sender);
        _send(tk.payoutA, na.value);
        _send(tk.payoutB, nb.value);
    }

    function _settleLeg(uint256 id, Note storage nt, Link[] calldata links, uint256 seq, bytes32 prev, bytes32 to, bytes32 tid, uint256 leg) private {
        uint256 n = links.length;
        if (n == 0 || n - 1 != seq) revert BadTicket();
        (bytes32[] memory prevs, bytes32[] memory msgs, ) = _walk(id, nt, links, true);
        Link calldata last = links[n - 1];
        if (prevs[n - 1] != prev || last.to != to || last.cond != tid) revert BadTicket();
        for (uint256 i; i < n; ++i) spentBy[prevs[i]] = msgs[i];
        spentBy[prevs[n]] = keccak256(abi.encode(SWAP_DONE_TAG, tid, leg));
    }

    // ------------------------------------------------------------------ hashes (the hub and CLI compute the same)

    function noteRoot(uint256 id) public view returns (bytes32) {
        Note storage nt = notes[id];
        return keccak256(abi.encode(NOTE_TAG, DOMAIN, id, uint256(nt.value), uint256(nt.lockUntil), nt.issuerKey));
    }

    function linkHash(uint256 id, uint256 seq, bytes32 prev, bytes32 to, bytes32 cond) public view returns (bytes32) {
        return keccak256(abi.encode(LINK_TAG, DOMAIN, id, seq, prev, to, cond));
    }

    function terminalHash(bytes32 prev, address payout, uint256 fee) public view returns (bytes32) {
        return keccak256(abi.encode(TERMINAL_TAG, DOMAIN, prev, payout, fee));
    }

    function ticketId(Ticket calldata tk) public view returns (bytes32) {
        return keccak256(bytes.concat(abi.encode(SWAP_TAG, DOMAIN, tk.noteA, tk.seqA, tk.prevA, tk.toA, tk.payoutA),
            abi.encode(tk.noteB, tk.seqB, tk.prevB, tk.toB, tk.payoutB, tk.deadline)));
    }

    /// What the issuer bond covers now: bond, outstanding, and whether it is still >= 150%.
    function issuerCover(address issuer) external view returns (uint256 bond, uint64 until, uint256 out, bool healthy) {
        Bond storage b = issuerBonds[issuer];
        out = outstanding[issuer];
        return (b.amount, b.until, out, b.amount * 10_000 >= out * BOND_BPS);
    }

    // ------------------------------------------------------------------ internals

    /// Checks every link's signature; returns prev[i] (what message i spends), msgs[i] (link i's hash) and
    /// keys[i] (holder i; keys[0] = the issuer key), with room for the terminal at index n.
    function _walk(uint256 id, Note storage nt, Link[] calldata links, bool swapLeg)
        private view returns (bytes32[] memory prevs, bytes32[] memory msgs, bytes32[] memory keys)
    {
        uint256 n = links.length;
        if (n > MAX_LINKS) revert TooManyLinks();
        prevs = new bytes32[](n + 1);
        msgs = new bytes32[](n + 1);
        keys = new bytes32[](n + 1);
        prevs[0] = noteRoot(id);
        keys[0] = nt.issuerKey;
        for (uint256 i; i < n; ++i) {
            Link calldata l = links[i];
            if (l.to == bytes32(0)) revert WrongKey();
            if (l.cond != bytes32(0) && !(swapLeg && i == n - 1) && !swapSettled[l.cond]) revert UnsettledSwap();
            bytes32 h = linkHash(id, i, prevs[i], l.to, l.cond);
            _check(keys[i], h, l.pk, l.sig);
            msgs[i] = h;
            prevs[i + 1] = h;
            keys[i + 1] = l.to;
        }
    }

    function _check(bytes32 key, bytes32 digest, bytes calldata pk, bytes calldata sig) private view {
        if (pk.length != PK_BYTES || keccak256(pk) != key) revert WrongKey();
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(VARIANT, digest, pk, sig));
        if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadSignature();
    }

    function _payout(uint256 id, uint256 amount, Terminal calldata t, uint256 n) private {
        if (t.payout == address(0) || t.fee > amount) revert BadFee();
        emit Redeemed(id, t.payout, amount - t.fee, t.fee, n, msg.sender);
        if (t.fee > 0) _send(msg.sender, t.fee);
        _send(t.payout, amount - t.fee);
    }

    function _send(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert SendFailed();
    }
}

contracts/ZetaphyOfflineOrders.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IOrdersERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}

interface IOrdersPermit {
    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
}

/// The ZETAPHY Swap router (zetaphy-dex/contracts/ZetaphyRouter.sol, Uniswap V2 names).
interface IOrdersRouter {
    function WETH() external view returns (address);
    function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external returns (uint256[] memory amounts);
}

interface IOrdersWrapped {
    function withdraw(uint256) external;
}

/// @title ZetaphyOfflineOrders: swap orders signed offline, filled by anyone (testnet, not audited)
/// @notice A maker signs an EIP-712 Order without a network (in the hub, or any wallet that signs typed
///         data offline): sell exactly `amountIn` of `tokenIn` for at least `minAmountOut` of `tokenOut`
///         (after the relayer's fee), until `deadline`. The signed order travels as a QR code or text;
///         whoever brings it online calls fill() and earns `relayerFee`, paid in tokenOut out of the swap.
///
///         fill(order, sig, path): pulls tokenIn from the maker (an approve of this contract, or an
///         EIP-2612 permit through fillWithPermit), swaps it on the ZETAPHY Swap router with
///         amountOutMin = minAmountOut + relayerFee, then pays the maker everything but the fee and
///         the caller the fee. All or nothing: no partial fills. The relayer chooses the route
///         (`path`, empty = the direct pool) but cannot take more than the fee: the maker's minimum
///         is checked on what the maker actually received.
///
///         tokenOut = address(0) means native ZETAPHY: the route ends in the router's wrapped coin
///         (WZETAPHY, or ZETAPHY's native ERC-20), which is unwrapped and sent as coins. To SELL native
///         ZETAPHY offline, wrap it first (tokenIn = WZETAPHY) and approve this contract.
///
///         Replay: one nonce per order in a per-maker bitmap (Uniswap Permit2 style); cancel(nonce) or
///         cancelWord(wordPos, mask) burns nonces. The EIP-712 domain binds the chain id and this
///         contract. No owner, no fee of its own, no upgrade. nonReentrant everywhere; the nonce is
///         spent before any call out.
contract ZetaphyOfflineOrders {
    struct Order {
        address maker;
        address tokenIn;
        address tokenOut;     // address(0) = native ZETAPHY
        uint256 amountIn;
        uint256 minAmountOut; // what the maker gets at least, after the relayer fee
        uint256 deadline;
        uint256 nonce;
        uint256 relayerFee;   // in tokenOut, to whoever fills
    }

    struct Permit {
        uint256 value;
        uint256 deadline;
        uint8 v;
        bytes32 r;
        bytes32 s;
    }

    bytes32 public constant ORDER_TYPEHASH = keccak256(
        "Order(address maker,address tokenIn,address tokenOut,uint256 amountIn,uint256 minAmountOut,uint256 deadline,uint256 nonce,uint256 relayerFee)"
    );
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    uint256 private constant HALF_N = 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;
    uint256 public constant MAX_HOPS = 3;

    address public immutable router;
    address public immutable wrapped;

    /// maker => word position (nonce >> 8) => bits of used nonces (nonce & 255)
    mapping(address => mapping(uint256 => uint256)) public nonceBitmap;
    uint256 private locked = 1;

    event OrderFilled(address indexed maker, uint256 indexed nonce, bytes32 indexed orderHash, address relayer,
        uint256 amountIn, uint256 amountOut, uint256 relayerFee);
    event NonceCancelled(address indexed maker, uint256 wordPos, uint256 mask);

    error Expired();
    error NonceUsed();
    error BadSignature();
    error BadOrder();
    error BadPath();
    error FeeOnTransfer();
    error InsufficientOutput(uint256 got, uint256 wanted);
    error TokenFailed();
    error SendFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    constructor(address router_) {
        router = router_;
        wrapped = IOrdersRouter(router_).WETH();
    }

    /// Only the wrapped coin pays native coins in here (when it unwraps).
    receive() external payable {
        if (msg.sender != wrapped) revert SendFailed();
    }

    // ------------------------------------------------------------------ EIP-712

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY Offline Orders"), keccak256("1"), block.chainid, address(this)));
    }

    function orderHash(Order calldata o) public pure returns (bytes32) {
        return keccak256(abi.encode(ORDER_TYPEHASH, o.maker, o.tokenIn, o.tokenOut, o.amountIn, o.minAmountOut, o.deadline, o.nonce, o.relayerFee));
    }

    /// The digest the maker signs (eth_signTypedData_v4 gives the same).
    function digest(Order calldata o) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), orderHash(o)));
    }

    function isNonceUsed(address maker, uint256 nonce) public view returns (bool) {
        return nonceBitmap[maker][nonce >> 8] & (1 << (nonce & 0xff)) != 0;
    }

    // ------------------------------------------------------------------ maker

    function cancel(uint256 nonce) external {
        uint256 mask = 1 << (nonce & 0xff);
        nonceBitmap[msg.sender][nonce >> 8] |= mask;
        emit NonceCancelled(msg.sender, nonce >> 8, mask);
    }

    /// Burns every nonce of word `wordPos` whose bit is set in `mask`.
    function cancelWord(uint256 wordPos, uint256 mask) external {
        nonceBitmap[msg.sender][wordPos] |= mask;
        emit NonceCancelled(msg.sender, wordPos, mask);
    }

    // ------------------------------------------------------------------ anyone (the relayer)

    /// Fills a signed order; returns what the maker received. Simulate it with eth_call first.
    function fill(Order calldata o, bytes calldata sig, address[] calldata path) external nonReentrant returns (uint256) {
        return _fill(o, sig, path);
    }

    /// The same, after the maker's EIP-2612 permit of tokenIn to this contract (a permit that fails, e.g.
    /// one somebody already used, is skipped: the fill then needs the allowance to be there anyway).
    function fillWithPermit(Order calldata o, bytes calldata sig, address[] calldata path, Permit calldata p)
        external nonReentrant returns (uint256)
    {
        try IOrdersPermit(o.tokenIn).permit(o.maker, address(this), p.value, p.deadline, p.v, p.r, p.s) {} catch {}
        return _fill(o, sig, path);
    }

    // ------------------------------------------------------------------ internals

    function _fill(Order calldata o, bytes calldata sig, address[] calldata path) private returns (uint256 toMaker) {
        if (block.timestamp > o.deadline) revert Expired();
        if (o.maker == address(0) || o.amountIn == 0 || o.tokenIn == address(0) || o.tokenIn == o.tokenOut || o.tokenIn == address(this)) revert BadOrder();
        address outToken = o.tokenOut == address(0) ? wrapped : o.tokenOut;
        if (outToken == o.tokenIn) revert BadOrder();
        _checkPath(path, o.tokenIn, outToken);
        bytes32 h = orderHash(o);
        if (_recover(keccak256(abi.encodePacked("\x19\x01", domainSeparator(), h)), sig) != o.maker) revert BadSignature();
        _useNonce(o.maker, o.nonce);
        uint256 got = _pullAndSwap(o, path, outToken);
        toMaker = got - o.relayerFee;
        _payOut(o, outToken, got, toMaker);
        emit OrderFilled(o.maker, o.nonce, h, msg.sender, o.amountIn, toMaker, o.relayerFee);
    }

    /// Pulls exactly amountIn (fee-on-transfer refused), swaps it on the router to this contract; returns
    /// the output received, at least minAmountOut + relayerFee.
    function _pullAndSwap(Order calldata o, address[] calldata path, address outToken) private returns (uint256 got) {
        IOrdersERC20 tin = IOrdersERC20(o.tokenIn);
        uint256 inBefore = tin.balanceOf(address(this));
        _safe(o.tokenIn, abi.encodeCall(IOrdersERC20.transferFrom, (o.maker, address(this), o.amountIn)));
        if (tin.balanceOf(address(this)) - inBefore != o.amountIn) revert FeeOnTransfer();
        uint256 want = o.minAmountOut + o.relayerFee;
        uint256 outBefore = IOrdersERC20(outToken).balanceOf(address(this));
        _safe(o.tokenIn, abi.encodeCall(IOrdersERC20.approve, (router, o.amountIn)));
        _swap(o, path, outToken, want);
        _safe(o.tokenIn, abi.encodeCall(IOrdersERC20.approve, (router, 0)));
        if (tin.balanceOf(address(this)) != inBefore) revert BadPath(); // the router took all of amountIn
        got = IOrdersERC20(outToken).balanceOf(address(this)) - outBefore;
        if (got < want) revert InsufficientOutput(got, want);
    }

    function _swap(Order calldata o, address[] calldata path, address outToken, uint256 want) private {
        if (path.length != 0) {
            IOrdersRouter(router).swapExactTokensForTokens(o.amountIn, want, path, address(this), o.deadline);
            return;
        }
        address[] memory direct = new address[](2);
        direct[0] = o.tokenIn;
        direct[1] = outToken;
        IOrdersRouter(router).swapExactTokensForTokens(o.amountIn, want, direct, address(this), o.deadline);
    }

    /// The maker gets `toMaker` (checked on what it actually received), the caller the relayer fee.
    function _payOut(Order calldata o, address outToken, uint256 got, uint256 toMaker) private {
        if (o.tokenOut == address(0)) {
            IOrdersWrapped(wrapped).withdraw(got);
            // WZETAPHY pays the coins in; ZETAPHY's native ERC-20 already holds them (its withdraw is a no-op)
            if (address(this).balance < got) revert TokenFailed();
            _sendNative(o.maker, toMaker);
            if (o.relayerFee != 0) _sendNative(msg.sender, o.relayerFee);
            return;
        }
        uint256 makerBefore = IOrdersERC20(outToken).balanceOf(o.maker);
        _safe(outToken, abi.encodeCall(IOrdersERC20.transfer, (o.maker, toMaker)));
        uint256 makerGot = IOrdersERC20(outToken).balanceOf(o.maker) - makerBefore;
        if (makerGot < o.minAmountOut) revert InsufficientOutput(makerGot, o.minAmountOut);
        if (o.relayerFee != 0) _safe(outToken, abi.encodeCall(IOrdersERC20.transfer, (msg.sender, o.relayerFee)));
    }

    function _checkPath(address[] calldata path, address tokenIn, address outToken) private pure {
        if (path.length == 0) return;
        if (path.length < 2 || path.length > MAX_HOPS + 1 || path[0] != tokenIn || path[path.length - 1] != outToken) revert BadPath();
    }

    function _useNonce(address maker, uint256 nonce) private {
        uint256 bit = 1 << (nonce & 0xff);
        uint256 word = nonceBitmap[maker][nonce >> 8];
        if (word & bit != 0) revert NonceUsed();
        nonceBitmap[maker][nonce >> 8] = word | bit;
    }

    function _sendNative(address to, uint256 amount) private {
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert SendFailed();
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address got) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27;
        if ((v != 27 && v != 28) || uint256(s) > HALF_N) revert BadSignature();
        got = ecrecover(d, v, r, s);
        if (got == address(0)) revert BadSignature();
    }

    function _safe(address token, bytes memory data) private {
        if (token.code.length == 0) revert TokenFailed();
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length != 32 || !abi.decode(ret, (bool))))) revert TokenFailed();
    }
}

contracts/ZetaphyOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Pyth's IPyth read surface, with PythStructs.Price's layout (the real Pyth and ZetaphyPythRelay both answer it).
interface IPythPrice {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }
    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
}

/// TwapRecorder's surface.
interface ITwapSource {
    struct Twap {
        uint256 avg0;
        uint256 avg1;
        uint64 from;
        uint64 newest;
        uint16 observations;
        uint128 minDepth;
        uint256 maxSegmentGapBps;
    }
    function consult(address pair, uint32 window) external view returns (Twap memory);
    function record(address pair) external returns (bool);
}

interface IPairTokens {
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IDecimals {
    function decimals() external view returns (uint8);
}

/// @title ZetaphyOracle: one price per asset, or a clear revert
/// @notice price(asset) returns (value, updatedAt): `value` is the asset's price in
///         USD with 18 decimals (1e18 = $1 per whole token), `updatedAt` the oldest
///         source time behind it. When any guard fails it REVERTS with an error
///         naming what failed; it never returns a stale, lopsided or jumped value.
///         Sources, per asset (governance enables one or both):
///           a) a TWAP of a ZETAPHY DEX pair (TwapRecorder observations, the pair's
///              cumulative prices; the other token is a USD stablecoin counted at $1):
///              valid only over at least `window` seconds (from an observation at
///              most 2 x window old), with at least `minObservations` observations
///              in it, a pool depth (quote side, 18 decimals) of at least
///              `minLiquidity` at every observation and now, and no segment
///              between observations averaging more than `maxSegmentGapBps` away
///              from the window's average;
///           b) Pyth (IPyth.getPriceUnsafe; on ZETAPHY a ZetaphyPythRelay until Pyth
///              or a Hyperlane route is here): not older than `maxAge`, not dated
///              in the future, positive, confidence interval at most `maxConfBps`
///              of the price.
///         With both: they must agree within `maxDeviationBps` (else SourcesDeviate);
///         the value is Pyth's, anchored by the TWAP. Decimals are normalized
///         (token decimals, Pyth's exponent) to 18.
///         Circuit breaker: poke(asset) (anyone; a keeper, the relay) records a TWAP
///         observation and, if every guard passes, makes the live price the
///         reference. price() refuses a live price more than `maxChangeBps` from the
///         reference, or more than `maxWindowChangeBps` from the price at the start
///         of the current `changeWindow`. A poke that sees such a jump TRIPS the
///         breaker: the asset has no price until governance resets it (through the
///         timelock). poke() also logs DeviationTripped / StaleFeed / SourceProblem
///         for the bridge monitor (zetaphy bridge monitor).
///         Roles: governance (the ZetaphyTimelock) sets every parameter; guardians
///         (multisigs governance names) may pause a feed at once. Unpausing,
///         resetting a tripped breaker and any setting wait the timelock.
contract ZetaphyOracle {
    struct TwapConfig {
        address pair;            // zero: no TWAP source
        bool assetIsToken0;
        uint8 assetDecimals;
        uint8 quoteDecimals;
        uint32 window;           // seconds
        uint16 minObservations;
        uint16 maxSegmentGapBps;
        uint128 minLiquidity;    // quote-side depth, 18 decimals (USD)
    }
    struct PythConfig {
        bytes32 id;              // zero: no Pyth source
        uint32 maxAge;           // seconds
        uint16 maxConfBps;
    }
    struct Guards {
        uint16 maxDeviationBps;      // between the two sources
        uint16 maxChangeBps;         // from the reference (the last accepted price)
        uint16 maxWindowChangeBps;   // from the price at the start of the change window
        uint32 changeWindow;         // seconds
    }
    struct State {
        uint128 lastPrice;       // the reference (0: none yet, poke first)
        uint64 lastAt;
        bool paused;
        bool tripped;
        uint128 windowPrice;
        uint64 windowStart;
    }

    /// What went wrong with the live price (poke logs it; price() reverts with the matching error).
    enum Problem { None, NotConfigured, TwapUnavailable, TwapStale, TooFewObservations, LowLiquidity, TwapSpike,
        PythUnavailable, PythStale, PythInvalid, PythConfidence, SourcesDeviate }

    ITwapSource public immutable recorder;
    IPythPrice public pyth;
    address public governance;
    mapping(address => bool) public guardian;

    mapping(address => TwapConfig) public twapOf;
    mapping(address => PythConfig) public pythOf;
    mapping(address => Guards) public guardsOf;
    mapping(address => State) public stateOf;
    address[] private _assets;
    mapping(address => bool) public listed;

    uint256 public constant MAX_FUTURE = 60;   // seconds a Pyth publishTime may run ahead (clock skew)
    uint256 private constant BPS = 10_000;

    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event PythSet(address pyth);
    event TwapConfigured(address indexed asset, address pair, uint32 window, uint16 minObservations, uint16 maxSegmentGapBps, uint128 minLiquidity);
    event PythConfigured(address indexed asset, bytes32 id, uint32 maxAge, uint16 maxConfBps);
    event GuardsSet(address indexed asset, uint16 maxDeviationBps, uint16 maxChangeBps, uint16 maxWindowChangeBps, uint32 changeWindow);
    event FeedPaused(address indexed asset, address indexed by);
    event FeedUnpaused(address indexed asset);
    event CircuitBreakerReset(address indexed asset);
    event Poked(address indexed asset, uint256 price, uint256 updatedAt);
    event DeviationTripped(address indexed asset, uint256 twapPrice, uint256 pythPrice, uint256 bps);
    event StaleFeed(address indexed asset, uint8 source, uint256 updatedAt);   // source 1 TWAP, 2 Pyth
    event SourceProblem(address indexed asset, uint8 problem, uint256 a, uint256 b);
    event CircuitBreakerTripped(address indexed asset, uint256 price, uint256 ref, uint256 bps);

    error NotGovernance();
    error NotGuardian();
    error UnknownAsset(address asset);
    error FeedIsPaused(address asset);
    error BreakerTripped(address asset);
    error NoReference(address asset);
    error PriceJump(address asset, uint256 price, uint256 ref, uint256 bps);
    /// No source enabled, or no guards set (setGuards is required).
    error NotConfigured(address asset);
    error TwapUnavailable(address asset);
    error TwapStale(address asset, uint256 from);
    error TooFewObservations(address asset, uint256 have, uint256 need);
    error LowLiquidity(address asset, uint256 depth, uint256 need);
    error TwapSpike(address asset, uint256 bps, uint256 most);
    error PythUnavailable(address asset);
    error PythStale(address asset, uint256 publishTime);
    error PythInvalid(address asset);
    error PythConfidence(address asset, uint256 bps, uint256 most);
    error SourcesDeviate(address asset, uint256 twapPrice, uint256 pythPrice, uint256 bps);
    error BadConfig();

    constructor(address governance_, ITwapSource recorder_, IPythPrice pyth_) {
        if (governance_ == address(0) || address(recorder_) == address(0)) revert BadConfig();
        governance = governance_;
        recorder = recorder_;
        pyth = pyth_;
        emit GovernanceSet(governance_);
        emit PythSet(address(pyth_));
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    // ---- governance (the timelock) ----

    function setGovernance(address g) external onlyGov { if (g == address(0)) revert BadConfig(); governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }
    /// The Pyth contract (ZetaphyPythRelay now; Pyth itself once deployed on ZETAPHY). Zero: no Pyth.
    function setPyth(IPythPrice p) external onlyGov { pyth = p; emit PythSet(address(p)); }

    /// The TWAP source of `asset`: a DEX pair of `asset` and a USD stablecoin (pair zero: off).
    function setTwap(address asset, address pair, uint32 window, uint16 minObservations, uint16 maxSegmentGapBps, uint128 minLiquidity) external onlyGov {
        TwapConfig memory c;
        if (pair != address(0)) {
            address t0 = IPairTokens(pair).token0();
            address t1 = IPairTokens(pair).token1();
            if (asset != t0 && asset != t1) revert BadConfig();
            if (window < 60 || minObservations < 2 || maxSegmentGapBps == 0 || minLiquidity == 0) revert BadConfig();
            c = TwapConfig(pair, asset == t0, IDecimals(asset).decimals(), IDecimals(asset == t0 ? t1 : t0).decimals(),
                window, minObservations, maxSegmentGapBps, minLiquidity);
            if (c.quoteDecimals > 18 || c.assetDecimals > 30) revert BadConfig();
        }
        twapOf[asset] = c;
        _configured(asset);
        emit TwapConfigured(asset, pair, window, minObservations, maxSegmentGapBps, minLiquidity);
    }

    /// The Pyth feed of `asset` (id zero: off).
    function setPythFeed(address asset, bytes32 id, uint32 maxAge, uint16 maxConfBps) external onlyGov {
        if (id != bytes32(0) && (maxAge == 0 || maxConfBps == 0 || maxConfBps > BPS)) revert BadConfig();
        pythOf[asset] = PythConfig(id, maxAge, maxConfBps);
        _configured(asset);
        emit PythConfigured(asset, id, maxAge, maxConfBps);
    }

    function setGuards(address asset, uint16 maxDeviationBps, uint16 maxChangeBps, uint16 maxWindowChangeBps, uint32 changeWindow) external onlyGov {
        if (maxDeviationBps == 0 || maxChangeBps == 0 || maxWindowChangeBps < maxChangeBps || changeWindow == 0
            || maxDeviationBps > BPS || maxWindowChangeBps > BPS) revert BadConfig();
        guardsOf[asset] = Guards(maxDeviationBps, maxChangeBps, maxWindowChangeBps, changeWindow);
        _configured(asset);
        emit GuardsSet(asset, maxDeviationBps, maxChangeBps, maxWindowChangeBps, changeWindow);
    }

    /// Lifts a pause.
    function unpauseFeed(address asset) external onlyGov { stateOf[asset].paused = false; emit FeedUnpaused(asset); }

    /// Clears a tripped breaker and the reference: the next poke starts from the live price again.
    function resetCircuitBreaker(address asset) external onlyGov {
        State storage s = stateOf[asset];
        s.tripped = false;
        s.lastPrice = 0; s.lastAt = 0; s.windowPrice = 0; s.windowStart = 0;
        emit CircuitBreakerReset(asset);
    }

    function _configured(address asset) private {
        if (!listed[asset]) { listed[asset] = true; _assets.push(asset); }
        // A new source or guard starts from a fresh reference (the next poke).
        State storage s = stateOf[asset];
        s.lastPrice = 0; s.lastAt = 0; s.windowPrice = 0; s.windowStart = 0;
    }

    // ---- emergency: a guardian (or governance) stops a feed at once ----

    function pauseFeed(address asset) external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        stateOf[asset].paused = true;
        emit FeedPaused(asset, msg.sender);
    }

    // ---- consumers ----

    function assets() external view returns (address[] memory) { return _assets; }

    /// The asset's price in USD (18 decimals) and the time of its oldest source, or a revert naming why not.
    function price(address asset) external view returns (uint256 value, uint256 updatedAt) {
        if (!listed[asset]) revert UnknownAsset(asset);
        State memory s = stateOf[asset];
        if (s.paused) revert FeedIsPaused(asset);
        if (s.tripped) revert BreakerTripped(asset);
        Problem p; uint256 a; uint256 b;
        (value, updatedAt, p, a, b) = _live(asset);
        if (p != Problem.None) _fail(asset, p, a, b);
        if (s.lastPrice == 0) revert NoReference(asset);
        (uint256 ref, uint256 bps, bool ok) = _change(asset, s, value);
        if (!ok) revert PriceJump(asset, value, ref, bps);
    }

    /// The live price and what is wrong with it, without the circuit breaker (for monitors and tests).
    function livePrice(address asset) external view returns (uint256 value, uint256 updatedAt, Problem problem, uint256 a, uint256 b) {
        return _live(asset);
    }

    /// Anyone: records a TWAP observation and, when every guard passes, moves the reference
    /// to the live price. A jump beyond the change limits trips the breaker. Returns whether
    /// the reference moved.
    function poke(address asset) external returns (bool) {
        if (!listed[asset]) revert UnknownAsset(asset);
        address pair = twapOf[asset].pair;
        if (pair != address(0)) { try recorder.record(pair) {} catch {} }
        State storage s = stateOf[asset];
        if (s.paused || s.tripped) return false;
        (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) = _live(asset);
        if (p != Problem.None) {
            if (p == Problem.SourcesDeviate) emit DeviationTripped(asset, a, b, _bps(a, b));
            else if (p == Problem.TwapStale) emit StaleFeed(asset, 1, a);
            else if (p == Problem.PythStale) emit StaleFeed(asset, 2, a);
            else emit SourceProblem(asset, uint8(p), a, b);
            return false;
        }
        if (s.lastPrice != 0) {
            if (block.timestamp >= uint256(s.windowStart) + guardsOf[asset].changeWindow) {
                s.windowPrice = s.lastPrice;
                s.windowStart = uint64(block.timestamp);
            }
            (uint256 ref, uint256 bps, bool ok) = _change(asset, s, value);
            if (!ok) {
                s.tripped = true;
                emit CircuitBreakerTripped(asset, value, ref, bps);
                return false;
            }
        } else {
            s.windowPrice = uint128(value);
            s.windowStart = uint64(block.timestamp);
        }
        s.lastPrice = uint128(value);
        s.lastAt = uint64(at);
        emit Poked(asset, value, at);
        return true;
    }

    // ---- internals ----

    /// (reference, bps, ok): the live value against the reference and the window's start price.
    function _change(address asset, State memory s, uint256 value) private view returns (uint256, uint256, bool) {
        Guards memory g = guardsOf[asset];
        uint256 bps = _bps(value, s.lastPrice);
        if (bps > g.maxChangeBps) return (s.lastPrice, bps, false);
        if (s.windowPrice != 0 && block.timestamp < uint256(s.windowStart) + g.changeWindow) {
            uint256 wb = _bps(value, s.windowPrice);
            if (wb > g.maxWindowChangeBps) return (s.windowPrice, wb, false);
        }
        return (s.lastPrice, bps, true);
    }

    function _live(address asset) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        TwapConfig memory t = twapOf[asset];
        PythConfig memory y = pythOf[asset];
        if (t.pair == address(0) && (y.id == bytes32(0) || address(pyth) == address(0))) return (0, 0, Problem.NotConfigured, 0, 0);
        if (guardsOf[asset].maxChangeBps == 0) return (0, 0, Problem.NotConfigured, 0, 0); // guards are required
        uint256 twapValue; uint256 twapAt;
        if (t.pair != address(0)) {
            (twapValue, twapAt, p, a, b) = _twap(t);
            if (p != Problem.None) return (0, 0, p, a, b);
        }
        uint256 pythValue; uint256 pythAt;
        if (y.id != bytes32(0) && address(pyth) != address(0)) {
            (pythValue, pythAt, p, a, b) = _pyth(y);
            if (p != Problem.None) return (0, 0, p, a, b);
        }
        if (twapValue != 0 && pythValue != 0) {
            uint256 dev = _bps(twapValue, pythValue);
            if (dev > guardsOf[asset].maxDeviationBps) return (0, 0, Problem.SourcesDeviate, twapValue, pythValue);
            return (pythValue, pythAt < twapAt ? pythAt : twapAt, Problem.None, 0, 0);
        }
        return pythValue != 0 ? (pythValue, pythAt, Problem.None, 0, 0) : (twapValue, twapAt, Problem.None, 0, 0);
    }

    function _twap(TwapConfig memory t) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        ITwapSource.Twap memory w;
        try recorder.consult(t.pair, t.window) returns (ITwapSource.Twap memory r) { w = r; } catch { return (0, 0, Problem.TwapUnavailable, 0, 0); }
        if (block.timestamp - w.from > 2 * uint256(t.window)) return (0, 0, Problem.TwapStale, w.from, 0);
        if (w.observations < t.minObservations) return (0, 0, Problem.TooFewObservations, w.observations, t.minObservations);
        if (w.maxSegmentGapBps > t.maxSegmentGapBps) return (0, 0, Problem.TwapSpike, w.maxSegmentGapBps, t.maxSegmentGapBps);
        uint256 avg = t.assetIsToken0 ? w.avg0 : w.avg1;   // quote (raw) per asset (raw), UQ112x112
        if (avg == 0) return (0, 0, Problem.TwapUnavailable, 0, 0);
        // depth: sqrt(r0 r1) * sqrt(quote per asset) = the quote reserve; then 18 decimals
        uint256 depth = (uint256(w.minDepth) * _sqrt(avg)) >> 56;
        depth = depth * (10 ** uint256(18 - t.quoteDecimals));
        if (depth < t.minLiquidity) return (0, 0, Problem.LowLiquidity, depth, t.minLiquidity);
        value = _mulDiv(avg, 10 ** (uint256(t.assetDecimals) + 18), (10 ** uint256(t.quoteDecimals)) << 112);
        if (value == 0 || value > type(uint128).max) return (0, 0, Problem.TwapUnavailable, 0, 0);
        return (value, w.newest, Problem.None, 0, 0);
    }

    function _pyth(PythConfig memory y) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        IPythPrice.Price memory q;
        try pyth.getPriceUnsafe(y.id) returns (IPythPrice.Price memory r) { q = r; } catch { return (0, 0, Problem.PythUnavailable, 0, 0); }
        if (q.publishTime > block.timestamp + MAX_FUTURE) return (0, 0, Problem.PythInvalid, q.publishTime, 0);
        if (block.timestamp > q.publishTime && block.timestamp - q.publishTime > y.maxAge) return (0, 0, Problem.PythStale, q.publishTime, 0);
        if (q.price <= 0 || q.expo < -30 || q.expo > 12) return (0, 0, Problem.PythInvalid, 0, 0);
        uint256 raw = uint256(uint64(q.price));
        uint256 confBps = _mulDiv(uint256(q.conf), BPS, raw);
        if (confBps > y.maxConfBps) return (0, 0, Problem.PythConfidence, confBps, y.maxConfBps);
        int256 e = int256(q.expo) + 18;
        value = e >= 0 ? raw * (10 ** uint256(e)) : raw / (10 ** uint256(-e));
        if (value == 0 || value > type(uint128).max) return (0, 0, Problem.PythInvalid, 0, 0);
        return (value, q.publishTime > block.timestamp ? block.timestamp : q.publishTime, Problem.None, 0, 0);
    }

    function _fail(address asset, Problem p, uint256 a, uint256 b) private pure {
        if (p == Problem.NotConfigured) revert NotConfigured(asset);
        if (p == Problem.TwapUnavailable) revert TwapUnavailable(asset);
        if (p == Problem.TwapStale) revert TwapStale(asset, a);
        if (p == Problem.TooFewObservations) revert TooFewObservations(asset, a, b);
        if (p == Problem.LowLiquidity) revert LowLiquidity(asset, a, b);
        if (p == Problem.TwapSpike) revert TwapSpike(asset, a, b);
        if (p == Problem.PythUnavailable) revert PythUnavailable(asset);
        if (p == Problem.PythStale) revert PythStale(asset, a);
        if (p == Problem.PythInvalid) revert PythInvalid(asset);
        if (p == Problem.PythConfidence) revert PythConfidence(asset, a, b);
        revert SourcesDeviate(asset, a, b, _bps(a, b));
    }

    /// |x - y| / min(x, y), in bps.
    function _bps(uint256 x, uint256 y) private pure returns (uint256) {
        uint256 lo = x < y ? x : y;
        if (lo == 0) return type(uint256).max;
        return _mulDiv(x > y ? x - y : y - x, BPS, lo);
    }

    function _sqrt(uint256 x) private pure returns (uint256 z) {
        if (x == 0) return 0;
        z = x;
        uint256 y = x / 2 + 1;
        while (y < z) { z = y; y = (x / y + y) / 2; }
    }

    /// floor(a * b / d) with a 512-bit product (Remco Bloemen's mulDiv, MIT).
    function _mulDiv(uint256 a, uint256 b, uint256 d) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(a, b, not(0))
                prod0 := mul(a, b)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }
            if (prod1 == 0) return prod0 / d;
            require(d > prod1, "mulDiv");
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }
            uint256 twos = d & (~d + 1);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            result = prod0 * inv;
        }
    }
}

contracts/ZetaphyOutbox.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZetaphyOutbox: an append-only Merkle commitment of outgoing messages (ZETAPHY side)
/// @notice Why a commitment contract: a CometBFT header commits to the state (app_hash, an IAVL
///         multistore root) but NOT to EVM logs (last_results_hash only covers code, data and gas
///         of each tx result, and receipts/blooms live in a transient store). So events cannot be
///         proven to Ethereum from a header. Instead every message is appended to a SHA-256 Merkle
///         tree (depth 32, the Ethereum deposit-contract construction) and the root is kept in
///         STORAGE SLOT 0. The slot is in the evm IAVL store under 0x02 || address || slot, so
///         app_hash -> multistore proof -> IAVL proof -> slot 0 -> Merkle path proves a message.
///
///         root  = sha256(treeRoot || uint256(count))
///         leaf  = sha256(abi.encode(LEAF_TAG, block.chainid, address(this), nonce, sender,
///                                   dstChainId, receiver, sha256(payload)))
///         The nonce is the leaf index (0, 1, 2, ...): replay protection on the other side is a
///         bitmap of consumed nonces. No owner, no upgrade, no way to remove a message.
///         Testnet prototype, not audited. See docs/future/trustless-bridge.md.
contract ZetaphyOutbox {
    bytes32 public root;              // slot 0: proven by ZetaphyBridgeInbox (never zero after the constructor)
    uint64 public count;              // slot 1
    bytes32[32] private branch;       // slots 2..33

    bytes32 public constant LEAF_TAG = keccak256("zetaphy/outbox/v1");
    uint256 public constant DEPTH = 32;

    event MessageSent(uint64 indexed nonce, address indexed sender, uint256 indexed dstChainId, address receiver, bytes payload, bytes32 leaf, bytes32 root);

    constructor() {
        root = _root();
    }

    function send(uint256 dstChainId, address receiver, bytes calldata payload) external returns (uint64 nonce) {
        nonce = count;
        require(nonce < type(uint32).max, "full");
        bytes32 leaf = leafHash(block.chainid, address(this), nonce, msg.sender, dstChainId, receiver, sha256(payload));
        uint256 size = uint256(nonce) + 1;
        bytes32 node = leaf;
        for (uint256 h = 0; h < DEPTH; h++) {
            if (size & 1 == 1) { branch[h] = node; break; }
            node = sha256(abi.encodePacked(branch[h], node));
            size >>= 1;
        }
        count = nonce + 1;
        bytes32 r = _root();
        root = r;
        emit MessageSent(nonce, msg.sender, dstChainId, receiver, payload, leaf, r);
    }

    function leafHash(uint256 srcChainId, address outbox, uint64 nonce, address sender, uint256 dstChainId, address receiver, bytes32 payloadHash)
        public pure returns (bytes32)
    {
        return sha256(abi.encode(LEAF_TAG, srcChainId, outbox, nonce, sender, dstChainId, receiver, payloadHash));
    }

    function _root() private view returns (bytes32) {
        bytes32 node;
        bytes32 zero;
        uint256 size = count;
        for (uint256 h = 0; h < DEPTH; h++) {
            node = size & 1 == 1 ? sha256(abi.encodePacked(branch[h], node)) : sha256(abi.encodePacked(node, zero));
            zero = sha256(abi.encodePacked(zero, zero));
            size >>= 1;
        }
        return sha256(abi.encodePacked(node, uint256(count)));
    }
}

interface IZetaphyOutbox {
    function send(uint256 dstChainId, address receiver, bytes calldata payload) external returns (uint64);
}

interface IERC20Lockable {
    function transferFrom(address from, address to, uint256 v) external returns (bool);
}

/// @title ZetaphyLockbox: locks a token on ZETAPHY and sends "release `amount` to `recipient`"
///        through the outbox to one fixed receiver on one fixed destination chain.
/// @notice The tokens stay here (the way back is a mirror of this bridge, not in this prototype).
///         Everything is fixed at deployment: no admin.
contract ZetaphyLockbox {
    IERC20Lockable public immutable token;
    IZetaphyOutbox public immutable outbox;
    uint256 public immutable dstChainId;
    address public immutable dstReceiver;

    event Locked(uint64 indexed nonce, address indexed from, address indexed recipient, uint256 amount);

    constructor(IERC20Lockable token_, IZetaphyOutbox outbox_, uint256 dstChainId_, address dstReceiver_) {
        token = token_;
        outbox = outbox_;
        dstChainId = dstChainId_;
        dstReceiver = dstReceiver_;
    }

    function lock(uint256 amount, address recipient) external returns (uint64 nonce) {
        require(amount > 0 && recipient != address(0), "lock");
        require(token.transferFrom(msg.sender, address(this), amount), "transfer");
        nonce = outbox.send(dstChainId, dstReceiver, abi.encode(recipient, amount));
        emit Locked(nonce, msg.sender, recipient, amount);
    }
}

contracts/ZetaphyPQCheques.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPQChequeERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

/// @title ZetaphyPQCheques: offline cheques signed with ML-DSA-44 (testnet, not audited)
/// @notice The post-quantum twin of ZetaphyCheques (same channels, same rules, same events where they fit),
///         a separate contract so the deployed ZetaphyCheques and everything that reads it stay as they are.
///         The difference: a channel names an ML-DSA-44 public key (FIPS 204) instead of an ECDSA signer, and
///         cheques are checked by ZETAPHY's precompile at 0x…0900, the PQSettlement / QuantumWallet path.
///         No ecrecover anywhere: a quantum computer that derives secp256k1 keys cannot forge a cheque.
///
///         open(payee, token, amount, expiry, signerKey): signerKey is the 1312-byte ML-DSA-44 public key;
///         the contract keeps keccak256(signerKey) and emits the key itself (SignerKey event), so the payee
///         can read it from the chain once and check cheques offline afterwards.
///
///         A cheque: the signer signs chequeDigest(channelId, cumulativeAmount) =
///           keccak256(abi.encode("ZETAPHY PQCheques cheque v1", chainid, this, channelId, cumulativeAmount)),
///         the TOTAL promised so far; cash(id, cumulative, pk, sig) pays the payee the part not cashed yet,
///         never more than the deposit. Closing, challenge period, release, top-up and extend are exactly
///         those of ZetaphyCheques.
///
///         What stays classical: the payer funds the channel and closes it with its own account, and the
///         payee receives at its address. A quantum attacker who derives the payer's ECDSA key can do what
///         the payer can (top up, extend, close after expiry), not forge cheques; to make those steps
///         quantum-safe too, open the channel from a QuantumWallet or a native ML-DSA account.
///
///         No owner, no fee, no upgrade. Plain ERC-20s; fee-on-transfer tokens are refused. Checks-effects-
///         interactions and nonReentrant on every entry point.
contract ZetaphyPQCheques {
    struct Channel {
        address payer;
        uint64 expiry;     // the payer may start closing from here
        uint64 closeAt;    // 0 = open; else the end of the challenge period
        address payee;
        address token;     // address(0) = native ZETAPHY
        bytes32 signerKey; // keccak256 of the ML-DSA-44 public key whose cheques count
        uint256 deposit;   // everything deposited
        uint256 paid;      // everything cashed by the payee
        bool done;         // the payer took the remainder: the channel is over
    }

    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint8 public constant VARIANT = 44;
    uint256 public constant PK_BYTES = 1312;
    uint256 public constant CHALLENGE_PERIOD = 24 hours;
    uint256 public constant MAX_DURATION = 366 days;

    uint256 public channelCount;
    mapping(uint256 => Channel) public channels;
    uint256 private locked = 1;

    event ChannelOpened(uint256 indexed id, address indexed payer, address indexed payee, address token, uint256 amount, uint64 expiry, bytes32 signerKey);
    event SignerKey(uint256 indexed id, bytes publicKey);
    event ToppedUp(uint256 indexed id, uint256 amount, uint256 deposit);
    event Extended(uint256 indexed id, uint64 expiry);
    event Cashed(uint256 indexed id, address indexed payee, uint256 cumulative, uint256 amount, address submitter);
    event CloseStarted(uint256 indexed id, uint64 closeAt);
    event Released(uint256 indexed id);
    event Withdrawn(uint256 indexed id, address indexed payer, uint256 amount);

    error BadChannel();
    error NotPayer();
    error NotPayee();
    error BadAmount();
    error BadExpiry();
    error BadValue();
    error Closing();
    error NotClosing();
    error NotExpired();
    error ChallengeOpen();
    error ChannelDone();
    error WrongKey();
    error BadSignature();
    error NothingToCash();
    error FeeOnTransfer();
    error TokenFailed();
    error SendFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    /// The 32 bytes the channel's ML-DSA key signs for a cheque (src/qsafe/offline.js pqChequeDigest).
    function chequeDigest(uint256 id, uint256 cumulative) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY PQCheques cheque v1", block.chainid, address(this), id, cumulative));
    }

    // ------------------------------------------------------------------ payer

    /// Opens a channel to `payee` with `amount` of `token` (0 = native: send it as msg.value), cheques
    /// signed by the ML-DSA-44 key `signerKey`, closable from `expiry`. Returns the channel id (1, 2, ...).
    function open(address payee, address token, uint256 amount, uint64 expiry, bytes calldata signerKey)
        external payable nonReentrant returns (uint256 id)
    {
        if (payee == address(0) || payee == msg.sender || signerKey.length != PK_BYTES) revert BadChannel();
        if (amount == 0) revert BadAmount();
        if (expiry <= block.timestamp || expiry > block.timestamp + MAX_DURATION) revert BadExpiry();
        bytes32 keyHash = keccak256(signerKey);
        id = ++channelCount;
        channels[id] = Channel({ payer: msg.sender, expiry: expiry, closeAt: 0, payee: payee, token: token, signerKey: keyHash,
            deposit: amount, paid: 0, done: false });
        emit ChannelOpened(id, msg.sender, payee, token, amount, expiry, keyHash);
        emit SignerKey(id, signerKey);
        _pullIn(token, amount);
    }

    /// Adds to the deposit (payer only, not once closing).
    function topUp(uint256 id, uint256 amount) external payable nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (amount == 0) revert BadAmount();
        c.deposit += amount;
        emit ToppedUp(id, amount, c.deposit);
        _pullIn(c.token, amount);
    }

    /// Moves the expiry later (payer only, not once closing).
    function extend(uint256 id, uint64 expiry) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (expiry <= c.expiry || expiry > block.timestamp + MAX_DURATION) revert BadExpiry();
        c.expiry = expiry;
        emit Extended(id, expiry);
    }

    /// After the expiry: starts the challenge period, during which the payee can still cash.
    function startClose(uint256 id) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (block.timestamp < c.expiry) revert NotExpired();
        uint64 at = uint64(block.timestamp + CHALLENGE_PERIOD);
        c.closeAt = at;
        emit CloseStarted(id, at);
    }

    /// After the challenge period (or a release): the payer takes what was not cashed.
    function withdraw(uint256 id) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt == 0) revert NotClosing();
        if (block.timestamp < c.closeAt) revert ChallengeOpen();
        c.done = true;
        uint256 rest = c.deposit - c.paid;
        emit Withdrawn(id, c.payer, rest);
        if (rest != 0) _pay(c.token, c.payer, rest);
    }

    // ------------------------------------------------------------------ payee (and anyone)

    /// Cashes an ML-DSA-signed cheque: pays the payee min(cumulative, deposit) minus what it was already paid.
    /// `pk` is the channel's public key (keccak256(pk) == signerKey). Anyone may submit; the payee is paid.
    function cash(uint256 id, uint256 cumulative, bytes calldata pk, bytes calldata sig) external nonReentrant returns (uint256 amount) {
        Channel storage c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (c.done) revert ChannelDone();
        if (c.closeAt != 0 && block.timestamp >= c.closeAt) revert ChannelDone();
        if (keccak256(pk) != c.signerKey) revert WrongKey();
        if (!_pqValid(chequeDigest(id, cumulative), pk, sig)) revert BadSignature();
        uint256 upTo = cumulative < c.deposit ? cumulative : c.deposit;
        if (upTo <= c.paid) revert NothingToCash();
        amount = upTo - c.paid;
        c.paid = upTo;
        emit Cashed(id, c.payee, cumulative, amount, msg.sender);
        _pay(c.token, c.payee, amount);
    }

    /// The payee gives up the rest of the channel (after cashing): the payer may withdraw at once.
    function release(uint256 id) external nonReentrant {
        Channel storage c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (msg.sender != c.payee) revert NotPayee();
        if (c.done) revert ChannelDone();
        c.closeAt = uint64(block.timestamp);
        emit Released(id);
    }

    /// What cash(id, cumulative, …) would pay now with a valid cheque (0 if nothing / closed).
    function cashable(uint256 id, uint256 cumulative) external view returns (uint256) {
        Channel storage c = channels[id];
        if (c.payer == address(0) || c.done || (c.closeAt != 0 && block.timestamp >= c.closeAt)) return 0;
        uint256 upTo = cumulative < c.deposit ? cumulative : c.deposit;
        return upTo > c.paid ? upTo - c.paid : 0;
    }

    // ------------------------------------------------------------------ internals

    function _payerChannel(uint256 id) private view returns (Channel storage c) {
        c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (msg.sender != c.payer) revert NotPayer();
        if (c.done) revert ChannelDone();
    }

    function _pullIn(address token, uint256 amount) private {
        if (token == address(0)) {
            if (msg.value != amount) revert BadValue();
            return;
        }
        if (msg.value != 0) revert BadValue();
        if (token.code.length == 0) revert TokenFailed();
        uint256 before = IPQChequeERC20(token).balanceOf(address(this));
        _safe(token, abi.encodeCall(IPQChequeERC20.transferFrom, (msg.sender, address(this), amount)));
        if (IPQChequeERC20(token).balanceOf(address(this)) - before != amount) revert FeeOnTransfer();
    }

    function _pay(address token, address to, uint256 amount) private {
        if (token == address(0)) {
            (bool ok, ) = to.call{value: amount}("");
            if (!ok) revert SendFailed();
        } else {
            _safe(token, abi.encodeCall(IPQChequeERC20.transfer, (to, amount)));
        }
    }

    /// ML-DSA-44 verify through the precompile (variant ‖ digest ‖ pk ‖ sig -> uint256(1)), as PQSettlement.
    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        if (pk.length != PK_BYTES) return false; // fixed key length: the key / signature split cannot shift
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(VARIANT, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _safe(address token, bytes memory data) private {
        if (token.code.length == 0) revert TokenFailed();
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length != 32 || !abi.decode(ret, (bool))))) revert TokenFailed();
    }
}

contracts/ZetaphyPQOfflineOrders.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPQOrdersERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}

/// The ZETAPHY Swap router (zetaphy-dex/contracts/ZetaphyRouter.sol, Uniswap V2 names).
interface IPQOrdersRouter {
    function WETH() external view returns (address);
    function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external returns (uint256[] memory amounts);
}

interface IPQOrdersWrapped {
    function withdraw(uint256) external;
}

/// @title ZetaphyPQOfflineOrders: offline swap orders signed with ML-DSA-44, filled by anyone (testnet, not audited)
/// @notice The post-quantum twin of ZetaphyOfflineOrders, a separate contract so the deployed one and its users
///         stay as they are. Same Order, same fill rules (all or nothing, the relayer picks the route and earns
///         `relayerFee` in tokenOut, the maker's minimum is checked on what it actually received, native
///         ZETAPHY out is unwrapped, one nonce per order in a per-maker bitmap, cancel / cancelWord).
///
///         The difference: no ecrecover. A maker (any account: a QuantumWallet, a native ML-DSA account's
///         0x address, or an EOA) first names its ML-DSA-44 key with setPQKey(keccak256(publicKey)); orders
///         are then signed offline with that key over
///           digest(o) = keccak256(abi.encode("ZETAPHY PQOfflineOrders order v1", chainid, this, orderHash(o)))
///         and fill(o, pk, sig, path) checks keccak256(pk) == pqKeyOf[maker] and the signature with ZETAPHY's
///         ML-DSA precompile at 0x…0900 (the PQSettlement / QuantumWallet path). Rotating or clearing the key
///         (setPQKey again) voids every unfilled order signed with the old key.
///
///         Honest limits: tokenIn is pulled from the maker with transferFrom, so the allowance and the balance
///         are only as safe as the maker's account. For an end-to-end quantum-safe maker, use a QuantumWallet in
///         post-quantum-only mode (it calls setPQKey and approve through execute) or a native ML-DSA account.
///         There is no EIP-2612 permit path here: permits are ECDSA signatures.
contract ZetaphyPQOfflineOrders {
    struct Order {
        address maker;
        address tokenIn;
        address tokenOut;     // address(0) = native ZETAPHY
        uint256 amountIn;
        uint256 minAmountOut; // what the maker gets at least, after the relayer fee
        uint256 deadline;
        uint256 nonce;
        uint256 relayerFee;   // in tokenOut, to whoever fills
    }

    bytes32 public constant ORDER_TYPEHASH = keccak256(
        "Order(address maker,address tokenIn,address tokenOut,uint256 amountIn,uint256 minAmountOut,uint256 deadline,uint256 nonce,uint256 relayerFee)"
    );
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint8 public constant VARIANT = 44;
    uint256 public constant PK_BYTES = 1312;
    uint256 public constant MAX_HOPS = 3;

    address public immutable router;
    address public immutable wrapped;

    /// maker => keccak256 of its ML-DSA-44 public key (0 = none: its orders cannot fill)
    mapping(address => bytes32) public pqKeyOf;
    /// maker => word position (nonce >> 8) => bits of used nonces (nonce & 255)
    mapping(address => mapping(uint256 => uint256)) public nonceBitmap;
    uint256 private locked = 1;

    event PQKeySet(address indexed maker, bytes32 keyHash);
    event OrderFilled(address indexed maker, uint256 indexed nonce, bytes32 indexed orderHash, address relayer,
        uint256 amountIn, uint256 amountOut, uint256 relayerFee);
    event NonceCancelled(address indexed maker, uint256 wordPos, uint256 mask);

    error Expired();
    error NonceUsed();
    error NoKey();
    error WrongKey();
    error BadSignature();
    error BadOrder();
    error BadPath();
    error FeeOnTransfer();
    error InsufficientOutput(uint256 got, uint256 wanted);
    error TokenFailed();
    error SendFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    constructor(address router_) {
        router = router_;
        wrapped = IPQOrdersRouter(router_).WETH();
    }

    /// Only the wrapped coin pays native coins in here (when it unwraps).
    receive() external payable {
        if (msg.sender != wrapped) revert SendFailed();
    }

    // ------------------------------------------------------------------ digests

    function orderHash(Order calldata o) public pure returns (bytes32) {
        return keccak256(abi.encode(ORDER_TYPEHASH, o.maker, o.tokenIn, o.tokenOut, o.amountIn, o.minAmountOut, o.deadline, o.nonce, o.relayerFee));
    }

    /// The 32 bytes the maker's ML-DSA key signs (src/qsafe/offline.js pqOrderDigest).
    function digest(Order calldata o) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY PQOfflineOrders order v1", block.chainid, address(this), orderHash(o)));
    }

    function isNonceUsed(address maker, uint256 nonce) public view returns (bool) {
        return nonceBitmap[maker][nonce >> 8] & (1 << (nonce & 0xff)) != 0;
    }

    // ------------------------------------------------------------------ maker

    /// Names the caller's ML-DSA-44 key (keccak256 of the 1312-byte public key); 0 clears it.
    function setPQKey(bytes32 keyHash) external {
        pqKeyOf[msg.sender] = keyHash;
        emit PQKeySet(msg.sender, keyHash);
    }

    function cancel(uint256 nonce) external {
        uint256 mask = 1 << (nonce & 0xff);
        nonceBitmap[msg.sender][nonce >> 8] |= mask;
        emit NonceCancelled(msg.sender, nonce >> 8, mask);
    }

    /// Burns every nonce of word `wordPos` whose bit is set in `mask`.
    function cancelWord(uint256 wordPos, uint256 mask) external {
        nonceBitmap[msg.sender][wordPos] |= mask;
        emit NonceCancelled(msg.sender, wordPos, mask);
    }

    // ------------------------------------------------------------------ anyone (the relayer)

    /// Fills an ML-DSA-signed order; returns what the maker received. Simulate it with eth_call first.
    function fill(Order calldata o, bytes calldata pk, bytes calldata sig, address[] calldata path)
        external nonReentrant returns (uint256 toMaker)
    {
        address outToken = _checkOrder(o, path);
        bytes32 h = _checkSig(o, pk, sig);
        _useNonce(o.maker, o.nonce);
        return _swapAndPay(o, path, outToken, h);
    }

    // ------------------------------------------------------------------ internals

    /// Deadline, order shape and route; returns the token the swap ends in.
    function _checkOrder(Order calldata o, address[] calldata path) private view returns (address outToken) {
        if (block.timestamp > o.deadline) revert Expired();
        if (o.maker == address(0) || o.amountIn == 0 || o.tokenIn == address(0) || o.tokenIn == o.tokenOut || o.tokenIn == address(this)) revert BadOrder();
        outToken = o.tokenOut == address(0) ? wrapped : o.tokenOut;
        if (outToken == o.tokenIn) revert BadOrder();
        _checkPath(path, o.tokenIn, outToken);
    }

    function _swapAndPay(Order calldata o, address[] calldata path, address outToken, bytes32 h) private returns (uint256 toMaker) {
        uint256 got = _pullAndSwap(o, path, outToken);
        toMaker = got - o.relayerFee;
        _payOut(o, outToken, got, toMaker);
        emit OrderFilled(o.maker, o.nonce, h, msg.sender, o.amountIn, toMaker, o.relayerFee);
    }

    /// The maker's named key signed this order; returns its orderHash.
    function _checkSig(Order calldata o, bytes calldata pk, bytes calldata sig) private view returns (bytes32 h) {
        bytes32 key = pqKeyOf[o.maker];
        if (key == bytes32(0)) revert NoKey();
        if (keccak256(pk) != key) revert WrongKey();
        h = orderHash(o);
        if (!_pqValid(keccak256(abi.encode("ZETAPHY PQOfflineOrders order v1", block.chainid, address(this), h)), pk, sig)) revert BadSignature();
    }

    function _pullAndSwap(Order calldata o, address[] calldata path, address outToken) private returns (uint256 got) {
        IPQOrdersERC20 tin = IPQOrdersERC20(o.tokenIn);
        uint256 inBefore = tin.balanceOf(address(this));
        _safe(o.tokenIn, abi.encodeCall(IPQOrdersERC20.transferFrom, (o.maker, address(this), o.amountIn)));
        if (tin.balanceOf(address(this)) - inBefore != o.amountIn) revert FeeOnTransfer();
        uint256 want = o.minAmountOut + o.relayerFee;
        uint256 outBefore = IPQOrdersERC20(outToken).balanceOf(address(this));
        _safe(o.tokenIn, abi.encodeCall(IPQOrdersERC20.approve, (router, o.amountIn)));
        _swap(o, path, outToken, want);
        _safe(o.tokenIn, abi.encodeCall(IPQOrdersERC20.approve, (router, 0)));
        if (tin.balanceOf(address(this)) != inBefore) revert BadPath(); // the router took all of amountIn
        got = IPQOrdersERC20(outToken).balanceOf(address(this)) - outBefore;
        if (got < want) revert InsufficientOutput(got, want);
    }

    function _swap(Order calldata o, address[] calldata path, address outToken, uint256 want) private {
        uint256[] memory amounts;
        if (path.length != 0) {
            amounts = IPQOrdersRouter(router).swapExactTokensForTokens(o.amountIn, want, path, address(this), o.deadline);
        } else {
            address[] memory direct = new address[](2);
            direct[0] = o.tokenIn;
            direct[1] = outToken;
            amounts = IPQOrdersRouter(router).swapExactTokensForTokens(o.amountIn, want, direct, address(this), o.deadline);
        }
        // the router's own report must meet `want` too; _pullAndSwap then measures what actually arrived
        uint256 reported = amounts.length == 0 ? 0 : amounts[amounts.length - 1];
        if (reported < want) revert InsufficientOutput(reported, want);
    }

    function _payOut(Order calldata o, address outToken, uint256 got, uint256 toMaker) private {
        if (o.tokenOut == address(0)) {
            IPQOrdersWrapped(wrapped).withdraw(got);
            // WZETAPHY pays the coins in; ZETAPHY's native ERC-20 already holds them (its withdraw is a no-op)
            if (address(this).balance < got) revert TokenFailed();
            _sendNative(o.maker, toMaker);
            if (o.relayerFee != 0) _sendNative(msg.sender, o.relayerFee);
            return;
        }
        uint256 makerBefore = IPQOrdersERC20(outToken).balanceOf(o.maker);
        _safe(outToken, abi.encodeCall(IPQOrdersERC20.transfer, (o.maker, toMaker)));
        uint256 makerGot = IPQOrdersERC20(outToken).balanceOf(o.maker) - makerBefore;
        if (makerGot < o.minAmountOut) revert InsufficientOutput(makerGot, o.minAmountOut);
        if (o.relayerFee != 0) _safe(outToken, abi.encodeCall(IPQOrdersERC20.transfer, (msg.sender, o.relayerFee)));
    }

    function _checkPath(address[] calldata path, address tokenIn, address outToken) private pure {
        if (path.length == 0) return;
        if (path.length < 2 || path.length > MAX_HOPS + 1 || path[0] != tokenIn || path[path.length - 1] != outToken) revert BadPath();
    }

    function _useNonce(address maker, uint256 nonce) private {
        uint256 bit = 1 << (nonce & 0xff);
        uint256 word = nonceBitmap[maker][nonce >> 8];
        if (word & bit != 0) revert NonceUsed();
        nonceBitmap[maker][nonce >> 8] = word | bit;
    }

    function _sendNative(address to, uint256 amount) private {
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert SendFailed();
    }

    /// ML-DSA-44 verify through the precompile (variant ‖ digest ‖ pk ‖ sig -> uint256(1)), as PQSettlement.
    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        if (pk.length != PK_BYTES) return false;
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(VARIANT, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _safe(address token, bytes memory data) private {
        if (token.code.length == 0) revert TokenFailed();
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length != 32 || !abi.decode(ret, (bool))))) revert TokenFailed();
    }
}

contracts/ZetaphyPoints.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title BZTPHY: ZETAPHY testnet reward points
/// @notice People who run ZETAPHY validators and Neuro runners on the testnet earn BZTPHY.
///         When mainnet launches, BZTPHY balances at the freeze become ZETAPHY at mainnet genesis
///         (a share of a fixed pool; see zetaphy-chain/rewards/README.md).
///         BZTPHY cannot be transferred, approved or sold: it shows who did the work, not who bought it.
///         Wallets still show the balance (balanceOf, totalSupply, name, symbol, decimals, Transfer events).
contract ZetaphyPoints {
    string public constant name = "ZETAPHY Testnet Reward Points";
    string public constant symbol = "BZTPHY";
    uint8 public constant decimals = 18;

    address public owner;          // governance: sets the minter, the cap, revokes, freezes
    address public pendingOwner;
    address public minter;         // the daily award job
    uint256 public epochCap;       // most BZTPHY one epoch (UTC day) may award in total
    bool public frozen;            // after the freeze nothing changes: the balances are the snapshot

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(uint32 => uint256) public awardedInEpoch;
    mapping(uint32 => mapping(address => bool)) public awarded;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Awarded(uint32 indexed epoch, address indexed to, uint256 amount, bytes32 reason);
    event Revoked(address indexed from, uint256 amount, bytes32 reason);
    event MinterSet(address minter);
    event EpochCapSet(uint256 cap);
    event OwnershipTransferStarted(address indexed to);
    event OwnershipTransferred(address indexed from, address indexed to);
    event Frozen(uint256 totalSupply);

    error NotOwner();
    error NotMinter();
    error IsFrozen();
    error NonTransferable();
    error LengthMismatch();
    error AlreadyAwarded(uint32 epoch, address to);
    error OverEpochCap(uint32 epoch);
    error ZeroAddress();

    constructor(address owner_, address minter_, uint256 epochCap_) {
        if (owner_ == address(0)) revert ZeroAddress();
        owner = owner_;
        minter = minter_;
        epochCap = epochCap_;
        emit OwnershipTransferred(address(0), owner_);
        emit MinterSet(minter_);
        emit EpochCapSet(epochCap_);
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier notFrozen() {
        if (frozen) revert IsFrozen();
        _;
    }

    /// @notice Awards one epoch's points. Each address gets at most one award per epoch, so a
    ///         job that runs twice cannot pay twice, and an epoch never exceeds epochCap (a stolen
    ///         minter key can mint at most one cap per day, and the owner can revoke it).
    function award(uint32 epoch, address[] calldata to, uint256[] calldata amounts, bytes32 reason) external notFrozen {
        if (msg.sender != minter) revert NotMinter();
        if (to.length != amounts.length) revert LengthMismatch();
        uint256 before = awardedInEpoch[epoch];
        uint256 total = before;
        for (uint256 i = 0; i < to.length; i++) {
            address a = to[i];
            if (a == address(0)) revert ZeroAddress();
            if (awarded[epoch][a]) revert AlreadyAwarded(epoch, a);
            awarded[epoch][a] = true;
            total += amounts[i];
            balanceOf[a] += amounts[i];
            emit Transfer(address(0), a, amounts[i]);
            emit Awarded(epoch, a, amounts[i], reason);
        }
        if (total > epochCap) revert OverEpochCap(epoch);
        awardedInEpoch[epoch] = total;
        totalSupply += total - before;
    }

    /// @notice Takes points back (cheating, e.g. one person running many fake validators).
    function revoke(address from, uint256 amount, bytes32 reason) external onlyOwner notFrozen {
        uint256 b = balanceOf[from];
        if (amount > b) amount = b;
        balanceOf[from] = b - amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
        emit Revoked(from, amount, reason);
    }

    function setMinter(address m) external onlyOwner notFrozen {
        minter = m;
        emit MinterSet(m);
    }

    function setEpochCap(uint256 cap) external onlyOwner notFrozen {
        epochCap = cap;
        emit EpochCapSet(cap);
    }

    /// @notice Ends the program for good: the balances now are what mainnet genesis uses.
    function freeze() external onlyOwner notFrozen {
        frozen = true;
        minter = address(0);
        emit Frozen(totalSupply);
    }

    function transferOwnership(address to) external onlyOwner {
        pendingOwner = to;
        emit OwnershipTransferStarted(to);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotOwner();
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
    }

    // ---- ERC-20 surface that refuses to move points --------------------------------------
    function allowance(address, address) external pure returns (uint256) {
        return 0;
    }

    function transfer(address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }

    function approve(address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }
}

contracts/ZetaphyPythRelay.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice The part of Pyth's IPyth (pyth-sdk-solidity) ZETAPHY reads and writes,
///         with Pyth's own struct layout (PythStructs.Price / PriceFeed): the
///         ABI is the same as the real Pyth contract's, so ZetaphyOracle can be
///         pointed at real Pyth later (ZetaphyOracle.setPyth, through the timelock).
interface IPythLike {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }
    struct PriceFeed {
        bytes32 id;
        Price price;
        Price emaPrice;
    }
    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
    function getPriceNoOlderThan(bytes32 id, uint256 age) external view returns (Price memory);
    function getEmaPriceUnsafe(bytes32 id) external view returns (Price memory);
    function priceFeedExists(bytes32 id) external view returns (bool);
    function getUpdateFee(bytes[] calldata updateData) external view returns (uint256);
    function updatePriceFeeds(bytes[] calldata updateData) external payable;
}

/// @title ZetaphyPythRelay: Pyth prices on ZETAPHY before Pyth itself is here
/// @notice Pyth has no contract on ZETAPHY yet. Real Pyth checks each update
///         against Wormhole guardian signatures; this relay instead accepts an
///         update only when `threshold` distinct relayers (keys governance names)
///         submitted exactly the same one. Updates use Pyth's public format, the
///         one Pyth's MockPyth.createPriceFeedUpdateData builds:
///             abi.encode(PythStructs.PriceFeed feed, uint64 prevPublishTime)
///         so a relayer forwards what it reads from Pyth (Hermes) unchanged.
///         Like Pyth: an older update than the stored one is ignored (not an
///         error), the PriceFeedUpdate event is Pyth's, and reads revert with
///         PriceFeedNotFound / StalePrice. Unlike Pyth: the update fee is 0 and
///         sending value is refused.
///         Trust: the relayers (and governance, which names them) can publish any
///         price. ZetaphyOracle does not trust it alone: it checks staleness, the
///         confidence interval, the deviation from the DEX TWAP and a circuit
///         breaker. Later, either point ZetaphyOracle at real Pyth, or make a
///         Hyperlane receiver (a contract whose handle() takes Pyth updates from
///         a Hyperlane message out of a chain where Pyth verified them) the only
///         relayer, with threshold 1. Docs: zetaphy-network/README.md (oracle).
///         Governance: the ZetaphyTimelock.
contract ZetaphyPythRelay is IPythLike {
    address public governance;
    mapping(address => bool) public isRelayer;
    uint256 public relayerCount;
    uint8 public threshold;
    /// The furthest in the future a publishTime may be (clock skew).
    uint256 public constant MAX_FUTURE = 60;

    mapping(bytes32 => PriceFeed) private _feeds;
    /// keccak256(update) => relayer => submitted (an update is accepted once threshold relayers sent it)
    mapping(bytes32 => mapping(address => bool)) public submitted;
    /// Who submitted each update, so only those still relayers count
    /// (submissions()): a relayer governance removes no longer counts.
    mapping(bytes32 => address[]) private _submitters;

    event PriceFeedUpdate(bytes32 indexed id, uint64 publishTime, int64 price, uint64 conf);
    event RelayerSet(address indexed relayer, bool on);
    event ThresholdSet(uint8 threshold);
    event GovernanceSet(address governance);
    event Submitted(bytes32 indexed id, bytes32 indexed update, address indexed relayer, uint8 count);

    error NotGovernance();
    error NotRelayer();
    error PriceFeedNotFound();
    error StalePrice();
    error InvalidUpdateData();
    error NoFee();

    constructor(address governance_, address[] memory relayers, uint8 threshold_) {
        require(governance_ != address(0), "governance");
        governance = governance_;
        for (uint256 i = 0; i < relayers.length; i++) _setRelayer(relayers[i], true);
        require(threshold_ >= 1, "threshold");
        threshold = threshold_;
        emit GovernanceSet(governance_);
        emit ThresholdSet(threshold_);
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setRelayer(address who, bool on) external onlyGov { _setRelayer(who, on); }
    function setThreshold(uint8 t) external onlyGov { require(t >= 1, "threshold"); threshold = t; emit ThresholdSet(t); }
    function setGovernance(address g) external onlyGov { require(g != address(0), "governance"); governance = g; emit GovernanceSet(g); }

    function _setRelayer(address who, bool on) private {
        require(who != address(0), "relayer");
        if (on != isRelayer[who]) { if (on) relayerCount += 1; else relayerCount -= 1; }
        isRelayer[who] = on;
        emit RelayerSet(who, on);
    }

    // ---- Pyth's interface ----

    function getUpdateFee(bytes[] calldata) external pure returns (uint256) { return 0; }

    function updatePriceFeeds(bytes[] calldata updateData) external payable {
        if (msg.value != 0) revert NoFee();
        if (!isRelayer[msg.sender]) revert NotRelayer();
        for (uint256 i = 0; i < updateData.length; i++) {
            (PriceFeed memory f, ) = abi.decode(updateData[i], (PriceFeed, uint64));
            if (f.id == bytes32(0) || f.price.publishTime > block.timestamp + MAX_FUTURE) revert InvalidUpdateData();
            if (f.price.publishTime <= _feeds[f.id].price.publishTime) continue; // older or same: ignored, as Pyth does
            bytes32 u = keccak256(updateData[i]);
            uint8 n = submissions(u);
            if (!submitted[u][msg.sender]) {
                submitted[u][msg.sender] = true;
                _submitters[u].push(msg.sender);
                n += 1;
                emit Submitted(f.id, u, msg.sender, n);
            }
            if (n < threshold) continue;
            _feeds[f.id] = f;
            emit PriceFeedUpdate(f.id, uint64(f.price.publishTime), f.price.price, f.price.conf);
        }
    }

    /// How many current relayers submitted this update (keccak256 of it).
    function submissions(bytes32 u) public view returns (uint8 n) {
        address[] storage s = _submitters[u];
        for (uint256 i = 0; i < s.length; i++) if (isRelayer[s[i]]) n += 1;
    }

    function priceFeedExists(bytes32 id) public view returns (bool) { return _feeds[id].price.publishTime != 0; }

    function getPriceUnsafe(bytes32 id) public view returns (Price memory) {
        if (!priceFeedExists(id)) revert PriceFeedNotFound();
        return _feeds[id].price;
    }

    function getEmaPriceUnsafe(bytes32 id) external view returns (Price memory) {
        if (!priceFeedExists(id)) revert PriceFeedNotFound();
        return _feeds[id].emaPrice;
    }

    function getPriceNoOlderThan(bytes32 id, uint256 age) external view returns (Price memory p) {
        p = getPriceUnsafe(id);
        if (block.timestamp > p.publishTime && block.timestamp - p.publishTime > age) revert StalePrice();
    }
}

contracts/ZetaphyQuests.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZearlyQ {
    function transfer(address to, uint256 value) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

/// @title ZETAPHY Early quests: rewards in ZEARLY for things done on the ZETAPHY chain, each paid once per wallet
/// @notice The quests (first swap, liquidity, an Early Pass, staking…) are checked off chain from the chain's own
///         records (zetaphy-network/scripts/early.js quests); this contract pays from its ZEARLY balance and keeps,
///         on chain and for everyone to read, who was paid for which quest, so nobody is paid twice.
///         The operator (the quest job) sets each quest's reward and how many wallets it may pay, and pays.
///         It can take back only ZEARLY nobody was paid. Testnet; no value (zetaphy-chain/rewards/EARLY.md).
contract ZetaphyQuests {
    uint256 public constant MAX_BATCH = 300;

    IZearlyQ public immutable token;
    address public operator;

    struct Quest { uint256 reward; uint32 cap; uint32 count; }
    mapping(uint8 => Quest) public quests;
    mapping(uint8 => mapping(address => bool)) public paid;
    mapping(address => uint256) public earned;

    event OperatorSet(address operator);
    event QuestSet(uint8 indexed quest, uint256 reward, uint32 cap);
    event QuestPaid(uint8 indexed quest, address indexed to, uint256 reward);
    event Withdrawn(address to, uint256 amount);

    error NotOperator();
    error ZeroAddress();
    error BadBatch();
    error NoQuest();
    error TransferFailed();

    modifier onlyOperator() { if (msg.sender != operator) revert NotOperator(); _; }

    constructor(address token_, address operator_) {
        if (token_ == address(0) || operator_ == address(0)) revert ZeroAddress();
        token = IZearlyQ(token_);
        operator = operator_;
        emit OperatorSet(operator_);
    }

    function setOperator(address o) external onlyOperator {
        if (o == address(0)) revert ZeroAddress();
        operator = o;
        emit OperatorSet(o);
    }

    /// @notice A quest's reward per wallet and the most wallets it pays in all (cap 0 = closed).
    function setQuest(uint8 q, uint256 reward, uint32 cap) external onlyOperator {
        quests[q].reward = reward;
        quests[q].cap = cap;
        emit QuestSet(q, reward, cap);
    }

    /// @notice Pays quest `q` to every wallet in `to` not paid for it yet (others are skipped: re-runs are safe),
    ///         until the quest's cap. Returns how many were paid.
    function pay(uint8 q, address[] calldata to) external onlyOperator returns (uint256 n) {
        if (to.length == 0 || to.length > MAX_BATCH) revert BadBatch();
        Quest storage s = quests[q];
        if (s.reward == 0) revert NoQuest();
        for (uint256 i; i < to.length && s.count < s.cap; ++i) {
            address a = to[i];
            if (a == address(0) || paid[q][a]) continue;
            paid[q][a] = true;
            s.count += 1;
            earned[a] += s.reward;
            n++;
            if (!token.transfer(a, s.reward)) revert TransferFailed();
            emit QuestPaid(q, a, s.reward);
        }
    }

    /// @notice Which of quests 0..n-1 a wallet has been paid for (for the hub's Early page).
    function progress(address a, uint8 n) external view returns (bool[] memory done) {
        done = new bool[](n);
        for (uint8 i; i < n; ++i) done[i] = paid[i][a];
    }

    /// @notice Takes back ZEARLY nobody was paid (e.g. after the quests end).
    function withdraw(address to, uint256 amount) external onlyOperator {
        if (to == address(0)) revert ZeroAddress();
        if (!token.transfer(to, amount)) revert TransferFailed();
        emit Withdrawn(to, amount);
    }
}

contracts/ZkIdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZkPoseidonT3 {
    function poseidon(uint256[2] calldata x) external pure returns (uint256);
}

interface IZkIdentityVerifier {
    function verifyProof(uint256[2] calldata a, uint256[2][2] calldata b, uint256[2] calldata c, uint256[5] calldata pub)
        external view returns (bool);
}

interface IZkLabels {
    function labelOf(address account) external view returns (uint8);
    function humans(address account) external view returns (uint64 validUntil, uint8 method, bytes32 credentialHash, address attester);
}

interface IZkVouch {
    function levelOf(address account) external view returns (uint8);
}

/// @title ZkIdentityRegistry: private identities for labelled humans (testnet)
/// @notice docs/future/zk-identity.md. An account with a HUMAN label (LabelRegistry: a passkey checked on chain or by an
///   approved attester) registers an identity commitment C = Poseidon(secret, nullifierKey) that it made in its
///   browser. The registry stores the leaf Poseidon(C, level) in a Poseidon Merkle tree (depth 20), where level is
///   the account's uniqueness level when it registered or was last synced: 1 passkey human, 2 vouched unique human
///   (VouchRegistry; 1 if no VouchRegistry is set).
///   Later the person proves with a Groth16 proof (ZkIdentityVerifier) "my leaf is in the tree, my level >= X" and
///   reveals only nullifier = Poseidon(nullifierKey, scope), one per person per scope (PrivateAirdrop, PrivatePoll).
///
///   Which accounts are members is PUBLIC (registration is a transaction from the account). What is hidden is which
///   member made a given proof, and whether two proofs in different scopes came from the same member.
///
///   Binding rules (against making many identities from one label):
///   - an account keeps its first commitment forever: it can never register a second one;
///   - a passkey (credentialHash) is bound forever to the first commitment registered with it: moving the passkey to
///     a new account lets that account carry the SAME commitment (same nullifiers), never a new one;
///   - a commitment is in the tree at most once (one active account).
///   So a new identity needs a new account AND a new passkey (and, for level 2, new vouches): the anti-sybil
///   strength is exactly that of the labels and vouches (a person can make many passkeys; level 1 is a speed bump).
///
///   Labels expire and levels change: sync(account), callable by anyone, sets the leaf to the account's current
///   level, or removes it (leaf 0) when the account no longer holds a human label. Until someone calls it, the old
///   leaf stays provable. Replaced roots stay valid for rootTtl seconds, so proofs in flight survive new
///   registrations (and a removed member can still prove against a root younger than rootTtl).
///
///   Scopes: each app registers its scopes here (first come, first served), so two apps never share a nullifier
///   space by accident.
contract ZkIdentityRegistry {
    uint256 public constant SNARK_FIELD = 21888242871839275222246405745257275088548364400416034343698204186575808495617;
    uint256 public constant DEPTH = 20;
    uint8 public constant HUMAN = 1;

    IZkPoseidonT3 public immutable poseidon;
    IZkIdentityVerifier public immutable verifier;
    IZkLabels public immutable labels;
    IZkVouch public vouch;
    address public governance;
    uint64 public rootTtl;

    struct Member {
        uint256 commitment;
        uint32 index;
        uint8 level;  // 0 = not in the tree now
        bool active;
    }

    mapping(address => Member) public memberOf;
    mapping(bytes32 => uint256) public credentialCommitment; // passkey hash -> the commitment it is bound to
    mapping(uint256 => address) public commitmentAccount;    // commitment -> the account that holds it
    mapping(uint256 => address) public scopeOwner;
    mapping(uint256 => uint64) public rootReplacedAt;        // when a root stopped being the current one
    mapping(uint256 => bool) public rootSeen;
    uint256 public root;
    uint256 public leafCount;
    uint256[21] private zeros;                                // zeros[h]: an empty subtree of height h
    mapping(uint256 => uint256) private nodes;                // (h << 32) | index -> node (0 = empty)

    event Registered(address indexed account, uint256 indexed commitment, uint256 index, uint8 level, uint256 root);
    event Synced(address indexed account, uint256 index, uint8 level, uint256 root);
    event LeafSet(uint256 indexed index, uint256 leaf, uint256 root);
    event ScopeRegistered(uint256 indexed scope, address indexed owner);
    event ConfigSet(address vouch, uint64 rootTtl);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotHuman();
    error BadCommitment();
    error AccountBound(uint256 commitment);
    error PasskeyBound(uint256 commitment);
    error CommitmentTaken(address account);
    error AlreadyMember();
    error NotMember();
    error Unchanged();
    error TreeFull();
    error ScopeTaken(address owner);
    error BadScope();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(IZkPoseidonT3 poseidon_, IZkIdentityVerifier verifier_, IZkLabels labels_, IZkVouch vouch_, address governance_, uint64 rootTtl_) {
        poseidon = poseidon_;
        verifier = verifier_;
        labels = labels_;
        vouch = vouch_;
        governance = governance_;
        rootTtl = rootTtl_;
        uint256 z = 0;
        for (uint256 h = 0; h <= DEPTH; h++) {
            zeros[h] = z;
            z = _hash(z, z);
        }
        root = zeros[DEPTH];
        rootSeen[root] = true;
    }

    // ------------------------------------------------------------- reading

    /// The level `account` would be registered at now: 0 (no human label, or an agent), 1 or 2.
    function levelNow(address account) public view returns (uint8) {
        if (labels.labelOf(account) != HUMAN) return 0;
        if (address(vouch) == address(0)) return 1;
        uint8 l = vouch.levelOf(account);
        return l == 0 ? 1 : l;
    }

    /// The current root, or a replaced one younger than rootTtl.
    function isValidRoot(uint256 r) public view returns (bool) {
        if (r == root) return true;
        return rootSeen[r] && rootReplacedAt[r] != 0 && block.timestamp <= uint256(rootReplacedAt[r]) + rootTtl;
    }

    function zeroAt(uint256 h) external view returns (uint256) {
        return zeros[h];
    }

    /// Leaves [from, from + count) (0 = empty or removed), for provers rebuilding the tree locally.
    function leavesRange(uint256 from, uint256 count) external view returns (uint256[] memory out) {
        if (from >= leafCount) return new uint256[](0);
        if (count > leafCount - from) count = leafCount - from;
        out = new uint256[](count);
        for (uint256 i = 0; i < count; i++) out[i] = nodes[from + i];
    }

    /// Checks a membership proof: root known and recent, level >= minLevel, nullifier for `scope`, bound to `signalHash`.
    /// proof = [a0, a1, b00, b01, b10, b11, c0, c1] in the Solidity verifier's order (zkid-core.js proofWords).
    function verify(uint256 root_, uint256 nullifier, uint256 scope, uint256 signalHash, uint256 minLevel, uint256[8] calldata proof)
        public view returns (bool)
    {
        if (!isValidRoot(root_) || minLevel == 0) return false;
        return verifier.verifyProof(
            [proof[0], proof[1]], [[proof[2], proof[3]], [proof[4], proof[5]]], [proof[6], proof[7]],
            [root_, nullifier, scope, signalHash, minLevel]
        );
    }

    // ------------------------------------------------------------- members

    /// Registers the caller's identity commitment (made in its browser; reveals nothing about the secret).
    function register(uint256 commitment) external {
        if (commitment == 0 || commitment >= SNARK_FIELD) revert BadCommitment();
        uint8 level = levelNow(msg.sender);
        if (level == 0) revert NotHuman();
        Member storage m = memberOf[msg.sender];
        if (m.active) revert AlreadyMember();
        if (m.commitment != 0 && m.commitment != commitment) revert AccountBound(m.commitment);
        (, , bytes32 cred, ) = labels.humans(msg.sender);
        uint256 bound = credentialCommitment[cred];
        if (bound != 0 && bound != commitment) revert PasskeyBound(bound);
        address holder = commitmentAccount[commitment];
        if (holder != address(0) && holder != msg.sender) {
            _sync(holder); // drops the old holder if it lost its label (e.g. the passkey moved here)
            if (memberOf[holder].active) revert CommitmentTaken(holder);
        }
        credentialCommitment[cred] = commitment;
        commitmentAccount[commitment] = msg.sender;
        uint256 index;
        if (m.commitment == commitment) {
            index = m.index; // back after a removal: the same slot
        } else {
            index = leafCount;
            if (index >= 2 ** DEPTH) revert TreeFull();
            leafCount = index + 1;
        }
        memberOf[msg.sender] = Member({commitment: commitment, index: uint32(index), level: level, active: true});
        uint256 r = _setLeaf(index, _hash(commitment, level));
        emit Registered(msg.sender, commitment, index, level, r);
    }

    /// Sets `account`'s leaf to its level now, or removes it if it no longer qualifies. Anyone may call it.
    function sync(address account) external {
        Member storage m = memberOf[account];
        if (!m.active) revert NotMember();
        if (!_sync(account)) revert Unchanged();
    }

    function _sync(address account) private returns (bool changed) {
        Member storage m = memberOf[account];
        if (!m.active) return false;
        uint8 level = levelNow(account);
        if (level != 0) {
            // the account's passkey now may be bound to another identity: it no longer qualifies with this one
            (, , bytes32 cred, ) = labels.humans(account);
            uint256 bound = credentialCommitment[cred];
            if (bound != 0 && bound != m.commitment) level = 0;
        }
        if (level == m.level) return false;
        m.level = level;
        uint256 r;
        if (level == 0) {
            m.active = false;
            r = _setLeaf(m.index, 0);
        } else {
            r = _setLeaf(m.index, _hash(m.commitment, level));
        }
        emit Synced(account, m.index, level, r);
        return true;
    }

    // ------------------------------------------------------------- scopes

    /// Claims `scope` for the caller (an app contract). Nullifiers are per scope: one owner per scope.
    function registerScope(uint256 scope) external {
        if (scope == 0 || scope >= SNARK_FIELD) revert BadScope();
        address o = scopeOwner[scope];
        if (o != address(0)) revert ScopeTaken(o);
        scopeOwner[scope] = msg.sender;
        emit ScopeRegistered(scope, msg.sender);
    }

    // ------------------------------------------------------------- governance

    function setConfig(IZkVouch vouch_, uint64 rootTtl_) external onlyGovernance {
        vouch = vouch_;
        rootTtl = rootTtl_;
        emit ConfigSet(address(vouch_), rootTtl_);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- tree

    function _hash(uint256 a, uint256 b) private view returns (uint256) {
        return poseidon.poseidon([a, b]);
    }

    function _setLeaf(uint256 index, uint256 leaf) private returns (uint256 r) {
        uint256 node = leaf;
        uint256 i = index;
        for (uint256 h = 0; h < DEPTH; h++) {
            nodes[(h << 32) | i] = node;
            uint256 sib = nodes[(h << 32) | (i ^ 1)];
            if (sib == 0) sib = zeros[h];
            node = (i & 1) == 1 ? _hash(sib, node) : _hash(node, sib);
            i >>= 1;
        }
        r = node;
        uint256 old = root;
        if (old != r) {
            rootReplacedAt[old] = uint64(block.timestamp);
            root = r;
            rootReplacedAt[r] = 0;
            rootSeen[r] = true;
        }
        emit LeafSet(index, leaf, r);
    }
}

